INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0000', 'HDSAT-RW-M10X-W0000', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The curator''s notes were so ______ that even a reader unfamiliar with the period could follow the argument.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "ornate"}, {"id": "B", "text": "tentative"}, {"id": "C", "text": "terse"}, {"id": "D", "text": "lucid"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0000', 'D', ARRAY['D']::TEXT[], 'The phrase ''even a reader unfamiliar with the period could follow'' names the quality the notes need: clarity. ''Lucid'' means clear and easy to understand, so it is the only choice that explains why an outsider could follow the argument.', '{"C": "''Terse'' means brief to the point of abruptness, which would not help an unfamiliar reader follow anything.", "A": "''Ornate'' means heavily decorated, the opposite of the plain clarity the sentence praises.", "B": "''Tentative'' means uncertain, and hesitant notes would not make an argument easy to follow."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0001', 'HDSAT-RW-M10X-W0001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The dispute over water rights proved ______: three mediators resigned, and neither side would agree even to the wording of a meeting notice.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "generous"}, {"id": "B", "text": "intractable"}, {"id": "C", "text": "transient"}, {"id": "D", "text": "brittle"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0001', 'B', ARRAY['B']::TEXT[], 'The evidence is cumulative failure: mediators quit and the parties cannot agree even on a meeting notice. ''Intractable'' means stubbornly difficult to control or solve, which matches a dispute that defeats every attempt at settlement.', '{"D": "''Brittle'' describes something that breaks easily, not a dispute that resists every attempt at settlement.", "A": "''Generous'' is the opposite of what the resigned mediators and the stalled notice show.", "C": "''Transient'' means short-lived, but the sentence describes a conflict stubborn enough to outlast three mediators."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0002', 'HDSAT-RW-M10X-W0002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'Though the expedition is remembered for its drama, its daily log was ______, recording little more than mileage, weather and the state of the mules.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "prosaic"}, {"id": "B", "text": "lyrical"}, {"id": "C", "text": "perilous"}, {"id": "D", "text": "cryptic"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0002', 'A', ARRAY['A']::TEXT[], 'The contrast with the expedition''s dramatic reputation sets up an ordinary record. ''Prosaic'' means dull and matter-of-fact, exactly what a log of mileage, weather and mule condition is.', '{"B": "''Lyrical'' suggests expressive, songlike writing, but the log records only mileage, weather and mules.", "C": "''Perilous'' would describe danger, and the sentence lists ordinary bookkeeping instead.", "D": "''Cryptic'' means deliberately mysterious, while the entries named are plain and easy to read."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0003', 'HDSAT-RW-M10X-W0003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The trial''s results were ______: the treatment helped patients over sixty but showed no measurable effect on younger ones.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "conclusive"}, {"id": "B", "text": "unanimous"}, {"id": "C", "text": "negligible"}, {"id": "D", "text": "equivocal"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0003', 'D', ARRAY['D']::TEXT[], 'A result that helps one group and does not help another cannot be read as a single verdict. ''Equivocal'' means open to more than one interpretation, which is precisely the divided outcome described.', '{"A": "''Conclusive'' would settle the question, yet the results point in two directions.", "C": "''Negligible'' would mean the treatment did almost nothing, ignoring the benefit seen in older patients.", "B": "''Unanimous'' describes agreement among people, not a split pattern of results."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0004', 'HDSAT-RW-M10X-W0004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The committee adopted a ______ schedule, one it would replace once the survey of the new site was complete.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "meticulous"}, {"id": "B", "text": "punitive"}, {"id": "C", "text": "permanent"}, {"id": "D", "text": "provisional"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0004', 'D', ARRAY['D']::TEXT[], 'The clause ''one it would replace once the survey was complete'' defines the schedule as a stand-in. ''Provisional'' means arranged for the present and likely to change, which is exactly that arrangement.', '{"C": "''Permanent'' contradicts the plan to replace the schedule later.", "A": "''Meticulous'' praises care in detail, but the sentence is about the schedule''s temporary status.", "B": "''Punitive'' would mean designed as a punishment, which nothing in the sentence suggests."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0005', 'HDSAT-RW-M10X-W0005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'In a report crowded with technical detail, the most ______ finding was that the bridge''s expansion joints had been sealed shut.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "oblique"}, {"id": "B", "text": "negligible"}, {"id": "C", "text": "ornamental"}, {"id": "D", "text": "salient"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0005', 'D', ARRAY['D']::TEXT[], 'The sentence picks one finding out of many because it matters most. ''Salient'' means most noticeable or important, which fits a safety-relevant detail standing out from technical clutter.', '{"B": "''Negligible'' means too small to matter, the reverse of a finding singled out from a crowded report.", "A": "''Oblique'' means indirect, but a sealed joint is a direct and concrete fact.", "C": "''Ornamental'' describes decoration, not a structural fault worth noticing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0006', 'HDSAT-RW-M10X-W0006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The link between the two sightings was ______, resting on a single blurry photograph and the memory of one retired ranger.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "tenuous"}, {"id": "B", "text": "explicit"}, {"id": "C", "text": "reciprocal"}, {"id": "D", "text": "robust"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0006', 'A', ARRAY['A']::TEXT[], 'The evidence is deliberately described as slight: a blurry photograph and a single recollection. ''Tenuous'' means weak or flimsy, which matches a connection that barely holds.', '{"D": "''Robust'' means strong and dependable, the opposite of a case built on one photograph and one memory.", "B": "''Explicit'' means stated clearly, but the problem is the thinness of the evidence, not its clarity.", "C": "''Reciprocal'' describes something mutual, which the sentence never claims."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0007', 'HDSAT-RW-M10X-W0007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The monastery''s ______ cells contained a narrow bed, a stool and nothing else.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "austere"}, {"id": "B", "text": "provisional"}, {"id": "C", "text": "lavish"}, {"id": "D", "text": "cluttered"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0007', 'A', ARRAY['A']::TEXT[], 'A room with a bed, a stool and nothing else is defined by severe simplicity. ''Austere'' means plain and without comfort or ornament, which is exactly the cell described.', '{"C": "''Lavish'' means rich and abundant, the opposite of a bed, a stool and nothing else.", "D": "''Cluttered'' would mean filled with many objects, but the cell holds two.", "B": "''Provisional'' means temporary, which the sentence does not suggest."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0008', 'HDSAT-RW-M10X-W0008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'A ______ correspondent, she could fill a half-hour interview with anecdotes and never once repeat herself.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "taciturn"}, {"id": "B", "text": "laconic"}, {"id": "C", "text": "voluble"}, {"id": "D", "text": "reticent"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0008', 'C', ARRAY['C']::TEXT[], 'Filling thirty minutes with anecdotes and never repeating herself is fluent, abundant speech. ''Voluble'' means speaking readily and at length, which is the only choice consistent with that performance.', '{"D": "''Reticent'' means unwilling to speak freely, which contradicts filling a half-hour interview.", "B": "''Laconic'' means using very few words, the opposite of a stream of anecdotes.", "A": "''Taciturn'' means habitually silent, again the reverse of the behaviour described."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0009', 'HDSAT-RW-M10X-W0009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The editor''s ______ cuts removed three redundant scenes without touching a single line the author considered essential.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "arbitrary"}, {"id": "B", "text": "judicious"}, {"id": "C", "text": "hasty"}, {"id": "D", "text": "lavish"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0009', 'B', ARRAY['B']::TEXT[], 'The editor removed what was redundant and preserved what mattered, which is careful judgment. ''Judicious'' means showing good sense, precisely the quality of cuts that are both effective and respectful of the text.', '{"A": "''Arbitrary'' means done without reason, but the cuts are explained by redundancy.", "D": "''Lavish'' means abundant or extravagant, not selective and careful.", "C": "''Hasty'' means too quick, while the sentence describes precision in sparing essential lines."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0010', 'HDSAT-RW-M10X-W0010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'Critics called the score ______, noting that its main theme repeated a folk melody the composer had used in two earlier works.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "innovative"}, {"id": "B", "text": "derivative"}, {"id": "C", "text": "dissonant"}, {"id": "D", "text": "spare"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0010', 'B', ARRAY['B']::TEXT[], 'The evidence is reuse: the main theme repeats a melody heard twice before. ''Derivative'' means imitative of an earlier source rather than original, which is exactly the criticism the reviewers made.', '{"A": "''Innovative'' means introducing something new, but the theme is borrowed from the composer''s own earlier works.", "D": "''Spare'' describes thin texture, which the sentence never mentions.", "C": "''Dissonant'' describes harsh harmony, also absent from the sentence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0011', 'HDSAT-RW-M10X-W0011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The sensor''s ______ readings puzzled the technicians: every other gauge on the site agreed with the forecast.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "marginal"}, {"id": "B", "text": "anomalous"}, {"id": "C", "text": "consistent"}, {"id": "D", "text": "calibrated"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0011', 'B', ARRAY['B']::TEXT[], 'One sensor disagrees with every other gauge and with the forecast, so its readings are the exception. ''Anomalous'' means deviating from what is standard or expected, which explains the puzzlement.', '{"C": "''Consistent'' would mean the readings matched the others, which is what puzzled the technicians.", "D": "''Calibrated'' describes an instrument that has been adjusted correctly, not a reading that departs from every gauge.", "A": "''Marginal'' means slight, but the contrast is between one dissenting sensor and every other gauge."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0012', 'HDSAT-RW-M10X-W0012', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'Through ______ record-keeping, the archivist tracked every loan, repair and misfiling across four decades.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "assiduous"}, {"id": "B", "text": "cursory"}, {"id": "C", "text": "reluctant"}, {"id": "D", "text": "sporadic"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0012', 'A', ARRAY['A']::TEXT[], 'Keeping a complete record of every loan, repair and misfiling over forty years takes steady, painstaking attention. ''Assiduous'' means showing great care and perseverance, which matches that sustained effort.', '{"D": "''Sporadic'' means occurring at irregular intervals, which could not produce a four-decade record.", "C": "''Reluctant'' describes unwillingness, not the diligence implied by tracking every transaction.", "B": "''Cursory'' means hurried and superficial, the opposite of tracking every loan and repair."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0013', 'HDSAT-RW-M10X-W0013', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The citation turned out to be ______: the article it named had never been published, and its author did not exist.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "verbatim"}, {"id": "B", "text": "seminal"}, {"id": "C", "text": "obscure"}, {"id": "D", "text": "spurious"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0013', 'D', ARRAY['D']::TEXT[], 'A source that was never published and an author who never existed make the citation false rather than merely unfamiliar. ''Spurious'' means not genuine or valid, which fits a fabricated reference.', '{"C": "''Obscure'' means little known, but the citation names an article that never existed at all.", "B": "''Seminal'' means highly influential, which a nonexistent article cannot be.", "A": "''Verbatim'' means word for word, a description of quotation rather than of a fabricated source."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0014', 'HDSAT-RW-M10X-W0014', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'The model is appealingly ______, predicting the entire outcome from just two measured variables.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "redundant"}, {"id": "B", "text": "elaborate"}, {"id": "C", "text": "opaque"}, {"id": "D", "text": "parsimonious"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0014', 'D', ARRAY['D']::TEXT[], 'A model that predicts everything from two variables is economical in its assumptions. ''Parsimonious'' means unusually frugal or economical, and in this context it praises a simple explanation that accounts for a great deal.', '{"B": "''Elaborate'' means having many parts, the opposite of a model built on two variables.", "C": "''Opaque'' means hard to understand, but the sentence praises the model as appealing.", "A": "''Redundant'' means needlessly repetitive, which a two-variable model is not."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0015', 'HDSAT-RW-M10X-W0015', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The board was ______ that the deadline would not move, despite three requests for an extension.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "indifferent"}, {"id": "B", "text": "adamant"}, {"id": "C", "text": "amenable"}, {"id": "D", "text": "ambivalent"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0015', 'B', ARRAY['B']::TEXT[], 'Three requests for an extension were turned aside, which shows a fixed position. ''Adamant'' means refusing to be persuaded, exactly the stance described.', '{"D": "''Ambivalent'' means having mixed feelings, which would not explain a refusal to move the deadline.", "C": "''Amenable'' means open to suggestion, the opposite of resisting three requests.", "A": "''Indifferent'' suggests the board did not care, yet it repeatedly refused to change the date."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0016', 'HDSAT-RW-M10X-W0016', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The desert bloom is ______, lasting sometimes only a single morning before the heat closes the petals.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "perennial"}, {"id": "B", "text": "ephemeral"}, {"id": "C", "text": "dormant"}, {"id": "D", "text": "hardy"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0016', 'B', ARRAY['B']::TEXT[], 'The flower exists for a morning and then closes. ''Ephemeral'' means lasting for a very short time, which is the defining fact the sentence gives.', '{"D": "''Hardy'' means able to survive harsh conditions, while the bloom collapses in a morning.", "A": "''Perennial'' means lasting year after year, the opposite of a single morning.", "C": "''Dormant'' means temporarily inactive, not briefly alive and then gone."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0017', 'HDSAT-RW-M10X-W0017', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The ______ design survived two winters of heavy snow and a summer of record heat without a single repair.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "robust"}, {"id": "B", "text": "fragile"}, {"id": "C", "text": "ornate"}, {"id": "D", "text": "rigid"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0017', 'A', ARRAY['A']::TEXT[], 'The design endured extreme weather with no repairs, which is a test of strength and resilience. ''Robust'' means sturdy and able to withstand adverse conditions, exactly the performance described.', '{"B": "''Fragile'' means easily broken, which two winters and a summer without repair rule out.", "C": "''Ornate'' concerns decoration, not the ability to endure weather.", "D": "''Rigid'' means stiff and unyielding, which is not what the sentence''s evidence establishes."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0018', 'HDSAT-RW-M10X-W0018', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'Pressed by reporters, the spokesperson ______, praising the proposal''s goals while declining to say whether the agency supported it.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "conceded"}, {"id": "B", "text": "equivocated"}, {"id": "C", "text": "recanted"}, {"id": "D", "text": "elaborated"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0018', 'B', ARRAY['B']::TEXT[], 'Praising the goals while refusing to say whether the agency supports the proposal is a deliberate avoidance of commitment. ''Equivocated'' means used ambiguous language to avoid taking a clear position.', '{"A": "''Conceded'' means admitted a point, but the spokesperson gave no ground either way.", "D": "''Elaborated'' means added detail, while the answer deliberately avoided a clear position.", "C": "''Recanted'' means withdrew an earlier statement, which the sentence does not describe."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0019', 'HDSAT-RW-M10X-W0019', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'A second witness helped ______ the driver''s account, describing the same blue van and the same turning signal.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "refute"}, {"id": "B", "text": "postpone"}, {"id": "C", "text": "embellish"}, {"id": "D", "text": "corroborate"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0019', 'D', ARRAY['D']::TEXT[], 'Two independent accounts agree on the van and the signal. ''Corroborate'' means to confirm or support with additional evidence, which is exactly what the second witness did.', '{"A": "''Refute'' means disprove, but the second witness matched the first account.", "C": "''Embellish'' means add decorative detail, whereas the witness independently confirmed the same facts.", "B": "''Postpone'' means delay, which has nothing to do with two matching accounts."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0020', 'HDSAT-RW-M10X-W0020', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'Without regular use, a language learned in childhood may slowly ______, leaving only fragments of vocabulary.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "proliferate"}, {"id": "B", "text": "flourish"}, {"id": "C", "text": "solidify"}, {"id": "D", "text": "atrophy"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0020', 'D', ARRAY['D']::TEXT[], 'The sentence describes decline from disuse, ending with only fragments. ''Atrophy'' means to weaken or waste away through lack of use, which fits a language that fades when not practised.', '{"B": "''Flourish'' means thrive, the opposite of losing vocabulary through disuse.", "A": "''Proliferate'' means increase rapidly, which contradicts leaving only fragments.", "C": "''Solidify'' means become firmer, while the sentence describes gradual loss."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0021', 'HDSAT-RW-M10X-W0021', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The review ______ the film''s plotting as lazy and its dialogue as borrowed, and it recommended that readers skip the sequel.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "summarized"}, {"id": "B", "text": "castigated"}, {"id": "C", "text": "praised"}, {"id": "D", "text": "overlooked"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0021', 'B', ARRAY['B']::TEXT[], 'Calling the plotting lazy and the dialogue borrowed, then advising readers to skip the sequel, is severe criticism. ''Castigated'' means reprimanded or criticized harshly, which matches the review''s tone.', '{"C": "''Praised'' contradicts the complaints about lazy plotting and borrowed dialogue.", "A": "''Summarized'' means described briefly, but the review is clearly passing harsh judgment.", "D": "''Overlooked'' means failed to notice, which cannot describe a review that recommends skipping the sequel."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0022', 'HDSAT-RW-M10X-W0022', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'Out of ______ for the elders who had built the hall, the younger members left the original floorboards in place during the renovation.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "curiosity"}, {"id": "B", "text": "defiance"}, {"id": "C", "text": "deference"}, {"id": "D", "text": "indifference"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0022', 'C', ARRAY['C']::TEXT[], 'The younger members preserved something because of the elders who built it. ''Deference'' means respectful yielding to another''s judgment or standing, which explains a choice made out of respect rather than necessity.', '{"D": "''Indifference'' means lack of concern, which would not lead anyone to preserve something for another generation.", "B": "''Defiance'' means open resistance, the opposite of respecting the elders'' work.", "A": "''Curiosity'' means interest in learning, not the respect that motivated preserving the floorboards."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0023', 'HDSAT-RW-M10X-W0023', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The gallery''s ______ collection moved from silk scrolls to welded steel to field recordings, sometimes within a single room.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "sparse"}, {"id": "B", "text": "eclectic"}, {"id": "C", "text": "uniform"}, {"id": "D", "text": "derivative"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0023', 'B', ARRAY['B']::TEXT[], 'The collection combines widely different materials and traditions, even within one room. ''Eclectic'' means drawn from a broad range of sources, which describes that deliberate variety.', '{"C": "''Uniform'' means all the same, the opposite of scrolls, steel and field recordings together.", "A": "''Sparse'' means thinly spread, but the sentence stresses variety rather than scarcity.", "D": "''Derivative'' means imitative, which says nothing about the range of media on display."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0024', 'HDSAT-RW-M10X-W0024', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'A ______ archivist, she checked each folder''s date against three separate catalogues before filing it.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "gregarious"}, {"id": "B", "text": "improvident"}, {"id": "C", "text": "fastidious"}, {"id": "D", "text": "careless"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0024', 'C', ARRAY['C']::TEXT[], 'Verifying every date against three catalogues before filing shows anxious attention to detail. ''Fastidious'' means very attentive to accuracy and detail, which is the habit described.', '{"D": "''Careless'' contradicts the three-way cross-check before filing.", "A": "''Gregarious'' means sociable, which describes temperament rather than this working method.", "B": "''Improvident'' means failing to plan ahead, the reverse of checking every date carefully."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0025', 'HDSAT-RW-M10X-W0025', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'An ______ by temperament, she spent her career arguing that the city''s most beloved monuments were badly designed.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "mediator"}, {"id": "B", "text": "imitator"}, {"id": "C", "text": "traditionalist"}, {"id": "D", "text": "iconoclast"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0025', 'D', ARRAY['D']::TEXT[], 'Her career was built on challenging what the city revered. ''Iconoclast'' means a person who attacks cherished beliefs or institutions, which is precisely her stance toward the monuments.', '{"B": "''Imitator'' means someone who copies others, while she attacked established taste.", "A": "''Mediator'' means someone who settles disputes, which is not the role described.", "C": "''Traditionalist'' means someone who defends inherited practices, the opposite of attacking beloved monuments."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0026', 'HDSAT-RW-M10X-W0026', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The error was ______, the result of a drop-down menu that had been reordered overnight without anyone''s noticing.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "inadvertent"}, {"id": "B", "text": "systematic"}, {"id": "C", "text": "deliberate"}, {"id": "D", "text": "brazen"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0026', 'A', ARRAY['A']::TEXT[], 'A menu that changed overnight without anyone noticing makes the error accidental. ''Inadvertent'' means unintentional, which matches a mistake produced by an unnoticed interface change.', '{"C": "''Deliberate'' contradicts the unnoticed menu change that caused the mistake.", "B": "''Systematic'' means methodically planned, while the cause was an accidental reordering.", "D": "''Brazen'' means shameless, implying intent that the sentence explicitly denies."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0027', 'HDSAT-RW-M10X-W0027', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'Planting trees along the canal can ______ summer heat, lowering afternoon temperatures in nearby streets by several degrees.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "mitigate"}, {"id": "B", "text": "intensify"}, {"id": "C", "text": "replicate"}, {"id": "D", "text": "quantify"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0027', 'A', ARRAY['A']::TEXT[], 'The trees lower street temperatures, so they reduce the heat. ''Mitigate'' means to make less severe, which matches a measurable reduction in afternoon heat.', '{"B": "''Intensify'' means make worse, the opposite of lowering temperatures.", "D": "''Quantify'' means measure, but the sentence describes an effect on heat, not a calculation.", "C": "''Replicate'' means copy or repeat, which does not fit reducing heat."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0028', 'HDSAT-RW-M10X-W0028', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'The essay''s ______ lies in its attention to small differences, distinguishing, for example, between tolerated and encouraged.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "nuance"}, {"id": "B", "text": "bluster"}, {"id": "C", "text": "uniformity"}, {"id": "D", "text": "brevity"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0028', 'A', ARRAY['A']::TEXT[], 'The essay''s strength is its sensitivity to small distinctions between nearly synonymous ideas. ''Nuance'' means subtle difference in meaning, which is exactly what distinguishing tolerated from encouraged demonstrates.', '{"B": "''Bluster'' means loud, empty talk, which the essay''s careful distinctions contradict.", "C": "''Uniformity'' means sameness, the opposite of distinguishing between two close terms.", "D": "''Brevity'' means shortness, and the sentence praises precision rather than length."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0029', 'HDSAT-RW-M10X-W0029', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', '______ as ever, the engineer rejected the simpler design for the fourth time and returned to her original drawings.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "pliable"}, {"id": "B", "text": "obstinate"}, {"id": "C", "text": "indifferent"}, {"id": "D", "text": "cautious"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0029', 'B', ARRAY['B']::TEXT[], 'Four rejections and a return to the original drawings show a refusal to change course. ''Obstinate'' means stubbornly refusing to change one''s opinion or chosen course, which fits the repetition and the return.', '{"A": "''Pliable'' means easily influenced, the opposite of rejecting the same suggestion four times.", "C": "''Indifferent'' would mean she did not care, yet she keeps returning to her own drawings.", "D": "''Cautious'' suggests care about risk, not stubborn refusal to consider an alternative."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0030', 'HDSAT-RW-M10X-W0030', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'It is a ______ that the town''s busiest road is named Quiet Street, a fact that visitors never tire of pointing out.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "paradox"}, {"id": "B", "text": "platitude"}, {"id": "C", "text": "precedent"}, {"id": "D", "text": "consensus"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0030', 'A', ARRAY['A']::TEXT[], 'A noisy, busy road carrying the name Quiet Street is a contradiction between expectation and reality. ''Paradox'' means a situation that seems self-contradictory, which is exactly what visitors enjoy pointing out.', '{"D": "''Consensus'' means general agreement, which is not a contradiction between a name and a condition.", "C": "''Precedent'' means an earlier case used as a guide, not an ironic mismatch.", "B": "''Platitude'' means a flat, overused remark, while the sentence describes a contradictory fact."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0031', 'HDSAT-RW-M10X-W0031', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'A ______ approach to the shortage, the plan rented extra tankers instead of waiting for a permanent pipeline.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "doctrinaire"}, {"id": "B", "text": "sentimental"}, {"id": "C", "text": "dogmatic"}, {"id": "D", "text": "pragmatic"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0031', 'D', ARRAY['D']::TEXT[], 'Renting tankers instead of waiting for an ideal solution is a practical response to an immediate problem. ''Pragmatic'' means dealing with things sensibly and realistically, which the plan''s temporary fix demonstrates.', '{"C": "''Dogmatic'' means insisting on fixed principles regardless of results, while the plan adapts to a shortage.", "B": "''Sentimental'' means guided by emotion, not by a practical workaround.", "A": "''Doctrinaire'' means rigidly theoretical, the opposite of renting tankers now."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0032', 'HDSAT-RW-M10X-W0032', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Hard', 'multiple_choice', 'Although ______ about his own role, he spoke at length about the work of every colleague on the team.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "verbose"}, {"id": "B", "text": "reticent"}, {"id": "C", "text": "boastful"}, {"id": "D", "text": "candid"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0032', 'B', ARRAY['B']::TEXT[], 'The contrast is between saying little about himself and saying much about others. ''Reticent'' means not revealing one''s thoughts or feelings readily, which explains his silence about his own contribution.', '{"C": "''Boastful'' means talking proudly about oneself, the opposite of saying little about his own role.", "A": "''Verbose'' means using too many words, which contradicts saying little about himself.", "D": "''Candid'' means frank and open, while the sentence stresses what he withheld about himself."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0033', 'HDSAT-RW-M10X-W0033', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'Inspectors ______ the welds on every beam, comparing each one against the original specification.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "endorsed"}, {"id": "B", "text": "scrutinized"}, {"id": "C", "text": "duplicated"}, {"id": "D", "text": "ignored"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0033', 'B', ARRAY['B']::TEXT[], 'Comparing every weld against its specification is close, critical examination. ''Scrutinized'' means examined closely and thoroughly, which describes the inspectors'' method rather than its conclusion.', '{"D": "''Ignored'' contradicts the careful comparison against the specification.", "A": "''Endorsed'' means approved, but inspection involves examination before any judgment.", "C": "''Duplicated'' means copied, which is not what comparing a weld to a specification means."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0034', 'HDSAT-RW-M10X-W0034', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The team offered a ______ conclusion, noting that the sample was small and that a larger trial might reverse it.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "reckless"}, {"id": "B", "text": "unanimous"}, {"id": "C", "text": "tentative"}, {"id": "D", "text": "definitive"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0034', 'C', ARRAY['C']::TEXT[], 'The team hedges its result because the sample is small and a bigger trial might change it. ''Tentative'' means not certain or fixed, which captures that openly provisional conclusion.', '{"D": "''Definitive'' would mean final and authoritative, but the team invites a larger trial to overturn it.", "A": "''Reckless'' means careless of consequences, whereas the team is explicitly cautious.", "B": "''Unanimous'' describes everyone agreeing, not the confidence level of a finding."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0035', 'HDSAT-RW-M10X-W0035', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'Repeated delays ______ the contractor''s credibility, and by spring two clients had moved their projects elsewhere.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "hastened"}, {"id": "B", "text": "documented"}, {"id": "C", "text": "undermined"}, {"id": "D", "text": "bolstered"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0035', 'C', ARRAY['C']::TEXT[], 'The delays preceded two clients leaving, so they weakened the contractor''s standing. ''Undermined'' means lessened the effectiveness or credibility of something, which matches the loss of trust.', '{"D": "''Bolstered'' means strengthened, the opposite of clients leaving.", "A": "''Hastened'' means sped up, which does not explain lost credibility.", "B": "''Documented'' means recorded, a neutral act that would not drive clients away."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0036', 'HDSAT-RW-M10X-W0036', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'The proposal is ______ only if the city can secure the land before the grant expires in June.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "futile"}, {"id": "B", "text": "superfluous"}, {"id": "C", "text": "ornate"}, {"id": "D", "text": "viable"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0036', 'D', ARRAY['D']::TEXT[], 'The plan can succeed, but only under a stated condition. ''Viable'' means capable of working successfully, which is exactly what securing the land before June would make possible.', '{"A": "''Futile'' means pointless, but the sentence describes a conditional path to success.", "C": "''Ornate'' means elaborately decorated, which says nothing about whether a plan can work.", "B": "''Superfluous'' means unnecessary, whereas the plan hinges on one condition being met."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0037', 'HDSAT-RW-M10X-W0037', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'Scientists remain ______ of the early results, which come from a single laboratory and have not yet been repeated.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "enamored"}, {"id": "B", "text": "oblivious"}, {"id": "C", "text": "dismissive"}, {"id": "D", "text": "wary"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0037', 'D', ARRAY['D']::TEXT[], 'Results from one laboratory that have not been replicated call for caution rather than belief or rejection. ''Wary'' means feeling caution about possible problems, which fits the scientists'' guarded stance.', '{"C": "''Dismissive'' would mean rejecting the results outright, but caution is not rejection.", "B": "''Oblivious'' means unaware, while the scientists are clearly aware of the results'' limits.", "A": "''Enamored'' means enthusiastic, the opposite of caution about unrepeated findings."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0038', 'HDSAT-RW-M10X-W0038', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Easy', 'multiple_choice', 'Her ______ for the project was evident in the hours she spent repairing instruments no one else would touch.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "hesitation"}, {"id": "B", "text": "candor"}, {"id": "C", "text": "apathy"}, {"id": "D", "text": "zeal"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0038', 'D', ARRAY['D']::TEXT[], 'Long hours spent on neglected repairs show intense enthusiasm. ''Zeal'' means great energy or enthusiasm for a cause, which is the quality the sentence illustrates.', '{"C": "''Apathy'' means indifference, which contradicts hours of voluntary repair work.", "A": "''Hesitation'' means reluctance, the opposite of eagerly taking on neglected tasks.", "B": "''Candor'' means honesty, a quality of speech rather than of dedication to a project."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-W0039', 'HDSAT-RW-M10X-W0039', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Words in Context', 'Medium', 'multiple_choice', 'He answered with ______, admitting that he had misread the report and that the mistake was his alone.', 'Which choice completes the text with the most logical and precise word or phrase?', '[{"id": "A", "text": "candor"}, {"id": "B", "text": "pomposity"}, {"id": "C", "text": "evasion"}, {"id": "D", "text": "hostility"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-W0039', 'A', ARRAY['A']::TEXT[], 'Admitting a misreading and accepting sole responsibility is direct honesty. ''Candor'' means the quality of being open and sincere, which is exactly how the answer is described.', '{"C": "''Evasion'' means avoiding the question, while he admits the error directly.", "B": "''Pomposity'' means self-important display, which contradicts taking personal responsibility.", "D": "''Hostility'' means aggression, absent from a plain admission of fault."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-B0000', 'HDSAT-RW-M10X-B0000', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'Although the tide had turned ______ the crew kept the nets in the water until dusk.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ","}, {"id": "B", "text": ":"}, {"id": "C", "text": "—"}, {"id": "D", "text": ";"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0000', 'A', ARRAY['A']::TEXT[], 'An introductory dependent clause is separated from the main clause by a comma; the clause cannot stand alone, so a semicolon, colon or dash would misrepresent the structure.', '{"D": "A semicolon joins two independent clauses, but the opening clause is dependent.", "B": "A colon would introduce an explanation or a list, not a main clause after a dependent one.", "C": "A dash marks a sharp break, while this sentence needs the ordinary comma after an introductory clause."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-B0001', 'HDSAT-RW-M10X-B0001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'Because the samples had thawed in transit ______ the laboratory rejected the entire batch.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ";"}, {"id": "B", "text": ":"}, {"id": "C", "text": "—"}, {"id": "D", "text": ","}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
