INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0002', 'D', ARRAY['D']::TEXT[], 'The subordinate clause beginning with ''When'' is introductory, so a comma separates it from the main clause. A semicolon, colon or dash would signal a different relationship.', '{"A": "A semicolon needs an independent clause on both sides, and the opening clause is dependent.", "C": "A colon would promise a list or an explanation, neither of which follows.", "B": "A dash would create a dramatic pause that the neutral sentence does not support."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
