INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0004', 'C', ARRAY['C']::TEXT[], 'The sentence opens with a dependent clause, which takes a comma before the main clause. A semicolon would need two independent clauses, and a colon or dash would change the tone and logic.', '{"B": "The ''Since'' clause is dependent, so a semicolon cannot separate it from the main clause.", "D": "A colon would introduce an explanation, but the second clause is the result, not a definition.", "A": "A dash would mark a break in thought that is not present."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
