INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0005', 'D', ARRAY['D']::TEXT[], 'The introductory clause beginning with ''Before'' is dependent, so a comma marks the boundary with the main clause. The other marks all join or introduce structures this sentence lacks.', '{"C": "A semicolon cannot follow a dependent clause.", "A": "A colon would suggest that what follows explains the opening, which it does not.", "B": "A dash would make the review sound like an interruption rather than a scheduled step."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
