INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0007', 'D', ARRAY['D']::TEXT[], 'An introductory ''Unless'' clause is dependent and takes a comma before the main clause. The alternatives would each change the sentence''s structure rather than punctuate it.', '{"A": "The conditional clause cannot stand alone, so a semicolon is wrong.", "B": "A colon would need to introduce an explanation or list.", "C": "A dash would suggest an aside rather than a condition."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
