INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0008', 'D', ARRAY['D']::TEXT[], 'The concessive clause introduced by ''Even though'' is dependent, so a comma separates it from the main clause. A semicolon, colon or dash would each misread the sentence''s structure.', '{"B": "A semicolon would treat the dependent opening clause as an independent one.", "A": "A colon would promise a conclusion or a list, not the main clause of a concession.", "C": "A dash would break the sentence more sharply than the contrast requires."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
