INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0009', 'A', ARRAY['A']::TEXT[], 'A dependent clause beginning with ''Once'' is followed by a comma when it opens the sentence. The other marks require independent clauses or explanatory material that is not present.', '{"C": "The ''Once'' clause is dependent, so a semicolon is not available.", "D": "A colon would need to introduce an explanation or a list.", "B": "A dash would make a routine sequence sound like an abrupt turn."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
