INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0010', 'A', ARRAY['A']::TEXT[], 'Two independent clauses that are closely related but not explanatory are joined by a semicolon. The comma would splice them together, and the period would create a fragment after it.', '{"C": "A comma alone between two independent clauses creates a comma splice.", "B": "A colon would need the second clause to explain or list something in the first.", "D": "A period would leave the next clause beginning with a lowercase word, so it cannot end the sentence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
