INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0011', 'B', ARRAY['B']::TEXT[], 'The two clauses are independent and in contrast, so a semicolon is the correct joint. A colon would promise an explanation, and a period cannot sit before a lowercase word.', '{"D": "The comma alone cannot join two independent clauses.", "C": "The second clause reports a contrast, not an explanation of the first.", "A": "A period would leave the following clause starting lowercase and standing as a fragment."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
