INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0033', 'A', ARRAY['A']::TEXT[], 'The comma before ''but'' marks the boundary between two independent clauses. The other choices either omit required punctuation or combine marks incorrectly.', '{"B": "Two independent clauses joined by a conjunction still need the comma.", "D": "A semicolon cannot be followed by a coordinating conjunction in this structure.", "C": "''However'' would need a semicolon or a period before it, not a comma."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
