INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0034', 'B', ARRAY['B']::TEXT[], 'The coordinating conjunction ''but'' joins two independent clauses and takes a comma before it. Dropping the comma, doubling the joint or substituting ''however'' all produce errors.', '{"D": "The clause boundary needs a comma before the conjunction.", "A": "A semicolon followed by ''but'' is not standard punctuation.", "C": "A comma alone before ''however'' creates a comma splice."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-B0035', 'HDSAT-RW-M10X-B0035', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'The engine is efficient ______ it is expensive to maintain.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", but"}, {"id": "B", "text": "but"}, {"id": "C", "text": "; but"}, {"id": "D", "text": ", however"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0035', 'A', ARRAY['A']::TEXT[], 'A comma precedes ''but'' when the conjunction joins two independent clauses. The alternatives all misuse the boundary between the clauses.', '{"B": "Without the comma, the sentence runs the two clauses together.", "C": "A semicolon and a coordinating conjunction are not used together this way.", "D": "''However'' requires a different punctuation pattern from the comma shown here."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
