INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0036', 'A', ARRAY['A']::TEXT[], 'A long introductory prepositional phrase is followed by a comma before the main clause. The other marks would misrepresent the phrase as an independent clause or as an explanation.', '{"C": "A semicolon would join an introductory phrase to a main clause as if both were independent.", "D": "A colon would introduce an explanation that the main clause does not provide.", "B": "A dash would break the sentence more sharply than the neutral opening warrants."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
