INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0037', 'C', ARRAY['C']::TEXT[], 'The introductory phrase sets the time and is followed by a comma before the main clause. The other punctuation marks would each require a different structure.', '{"B": "The opening phrase is not an independent clause, so a semicolon is wrong.", "A": "A colon would promise a list or explanation rather than the main clause.", "D": "A dash would make a routine seasonal statement sound like an interruption."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
