INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0038', 'B', ARRAY['B']::TEXT[], 'The long introductory phrase is set off by a comma before the main clause. Semicolon, colon and dash all fail to punctuate this structure correctly.', '{"C": "A semicolon cannot follow a prepositional phrase.", "A": "A colon would need to introduce an explanation or list.", "D": "A dash would imply a dramatic break that the sentence does not have."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
