INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0039', 'D', ARRAY['D']::TEXT[], 'A comma separates the introductory phrase from the main clause. The other marks would signal relationships or structures the sentence does not contain.', '{"C": "The opening phrase cannot stand alone, so a semicolon is unavailable.", "A": "A colon has no explanation or list to introduce.", "B": "A dash would exaggerate the pause before the main clause."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
