INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0040', 'A', ARRAY['A']::TEXT[], 'The introductory prepositional phrase is followed by a comma before the main clause. The other options misread the phrase as independent or explanatory.', '{"C": "A semicolon would treat the introductory phrase as a full clause.", "D": "A colon would introduce an explanation rather than continue the sentence.", "B": "A dash would create a sharper break than the neutral opening calls for."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
