INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0041', 'C', ARRAY['C']::TEXT[], 'A conjunctive adverb joining two independent clauses needs a semicolon before it. The comma produces a splice, and the colon and period mispunctuate the connection.', '{"B": "A comma before ''however'' creates a comma splice between two independent clauses.", "A": "A colon would suggest that the second trial explains the first, which it does not.", "D": "A period would leave ''however'' beginning a lowercase sentence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
