INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0042', 'C', ARRAY['C']::TEXT[], '''Moreover'' is a conjunctive adverb, so the two independent clauses are joined by a semicolon. A comma would splice them together, and the other marks are structurally wrong.', '{"D": "The comma alone before ''moreover'' is a comma splice.", "B": "A colon would present the lower cost as an explanation of the safety result.", "A": "A period would leave ''moreover'' starting a lowercase sentence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
