INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0043', 'B', ARRAY['B']::TEXT[], 'The conjunctive adverb ''consequently'' links two independent clauses and takes a semicolon before it. The comma would splice the clauses, and the colon and period are incorrect here.', '{"D": "A comma before ''consequently'' would create a comma splice.", "A": "A colon would present the unknown count as an explanation rather than a result.", "C": "A period would leave ''consequently'' beginning a lowercase sentence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
