INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0044', 'D', ARRAY['D']::TEXT[], 'Two independent clauses linked by ''however'' need a semicolon before the adverb. The comma would be a splice, and the other marks would break the sentence.', '{"C": "A comma alone cannot join the clauses before ''however''.", "A": "A colon would imply an explanation of the rarity.", "B": "A period would leave ''however'' starting a lowercase sentence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-B0045', 'HDSAT-RW-M10X-B0045', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'The first map was drawn from memory ______ therefore, its distances are unreliable.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ","}, {"id": "B", "text": ";"}, {"id": "C", "text": ":"}, {"id": "D", "text": "."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0045', 'B', ARRAY['B']::TEXT[], 'The conjunctive adverb ''therefore'' introduces a result, so a semicolon joins it to the first clause. The alternative marks either splice the clauses or create a fragment.', '{"A": "The comma before ''therefore'' creates a comma splice.", "C": "A colon would present the unreliability as an explanation rather than a consequence.", "D": "A period would leave ''therefore'' beginning a lowercase sentence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-B0046', 'HDSAT-RW-M10X-B0046', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'The survey asked about sleep, exercise ______ diet.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", but"}, {"id": "B", "text": "; and"}, {"id": "C", "text": ", and"}, {"id": "D", "text": "and"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0046', 'C', ARRAY['C']::TEXT[], 'A list of three items takes a comma before ''and'', which separates the final item from the rest. The other options either omit the comma or introduce the wrong relationship.', '{"D": "Without the comma, the final item is not clearly separated in the series.", "A": "''But'' signals contrast, yet the three items are simply listed.", "B": "A semicolon is too heavy for items in a simple series."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-B0047', 'HDSAT-RW-M10X-B0047', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Easy', 'multiple_choice', 'The kit includes a trowel, a brush ______ a small sieve.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "and"}, {"id": "B", "text": "; and"}, {"id": "C", "text": ", but"}, {"id": "D", "text": ", and"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0047', 'D', ARRAY['D']::TEXT[], 'The series of three tools is closed by a comma plus ''and''. Dropping the comma blurs the list, and ''but'' or a semicolon introduces a relationship the list does not have.', '{"A": "The final item needs the comma that keeps the series parallel.", "C": "A contrast is not being drawn between the brush and the sieve.", "B": "A semicolon would break the list instead of closing it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-B0048', 'HDSAT-RW-M10X-B0048', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'The report covers rainfall, temperature ______ wind speed.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": "and"}, {"id": "B", "text": ", and"}, {"id": "C", "text": "; and"}, {"id": "D", "text": ", but"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0048', 'B', ARRAY['B']::TEXT[], 'The comma before ''and'' marks the final item in a list of three. The other choices either remove required punctuation or wrongly suggest contrast or a clause boundary.', '{"A": "Without the comma, the last item runs into the preceding one.", "D": "The three measurements are listed, not contrasted.", "C": "A semicolon would separate clauses, not items in a list."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-B0049', 'HDSAT-RW-M10X-B0049', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Standard English Conventions', 'Boundaries', 'Medium', 'multiple_choice', 'The course teaches mapping, sampling ______ analysis.', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '[{"id": "A", "text": ", but"}, {"id": "B", "text": ", and"}, {"id": "C", "text": "and"}, {"id": "D", "text": "; and"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-B0049', 'B', ARRAY['B']::TEXT[], 'A comma precedes ''and'' in a series of three items. The other options either drop the comma or misuse a contrastive conjunction or a semicolon.', '{"C": "The missing comma makes the series unclear.", "A": "There is no contrast between the skills being listed.", "D": "A semicolon does not belong between items in a simple series."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0000', 'HDSAT-RW-M10X-T0000', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The first batches of the new insulation lost almost no heat in laboratory tests. ______, outdoor trials in a wet climate showed that its performance fell by nearly a third.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "However"}, {"id": "B", "text": "Therefore"}, {"id": "C", "text": "For example"}, {"id": "D", "text": "In addition"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0000', 'A', ARRAY['A']::TEXT[], '''However'' marks the contrast between strong laboratory performance and much weaker outdoor performance; the other options claim a cause, an example or an addition that the sentences do not support.', '{"B": "The second sentence does not follow as a consequence of the first, so a causal transition is wrong.", "C": "The outdoor result is a conflicting finding, not an instance of the laboratory result.", "D": "The two results point in opposite directions, so an additive transition would misstate the relation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0001', 'HDSAT-RW-M10X-T0001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Hard', 'multiple_choice', 'A 2019 review found that children raised with two languages switched tasks no faster than their peers. ______, a later study of 1,200 adolescents reported a small but consistent advantage on the same tasks.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "By contrast"}, {"id": "B", "text": "Similarly"}, {"id": "C", "text": "For instance"}, {"id": "D", "text": "Consequently"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0001', 'A', ARRAY['A']::TEXT[], '''By contrast'' signals that the later study conflicts with the earlier review; the other choices would present the disagreement as a consequence, an example or an agreement.', '{"D": "The later study does not follow from the earlier review, so a result transition is wrong.", "C": "The later study is a separate investigation, not an example of the first finding.", "B": "The two studies reach different conclusions, so ''Similarly'' would hide the disagreement."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0002', 'HDSAT-RW-M10X-T0002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Samples of the alloy resisted corrosion for more than a decade in dry air. ______, the same alloy developed deep pits within months when exposed to salt spray.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Thus"}, {"id": "B", "text": "Moreover"}, {"id": "C", "text": "In contrast"}, {"id": "D", "text": "Namely"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0002', 'C', ARRAY['C']::TEXT[], '''In contrast'' sets the two exposures against each other: the alloy lasted in dry air and failed quickly in salt spray. The other options wrongly suggest cause, restatement or addition.', '{"A": "The salt-spray result is not a consequence of the dry-air result, so ''Thus'' is wrong.", "D": "The second sentence reports a different outcome rather than restating the first.", "B": "The sentences describe opposing outcomes, so an additive transition would be misleading."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0003', 'HDSAT-RW-M10X-T0003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The 1985 glacier survey recorded a terminus well below the ridge. ______, satellite images from 2020 place the terminus almost two kilometers farther up the valley.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Since then"}, {"id": "B", "text": "For example"}, {"id": "C", "text": "In other words"}, {"id": "D", "text": "Nevertheless"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0003', 'A', ARRAY['A']::TEXT[], '''Since then'' places the satellite measurement after the 1985 survey in time, which is exactly the relation between the two sentences. The other transitions signal contrast, example or restatement.', '{"D": "''Nevertheless'' would imply an unexpected exception, but the later measurement simply continues the record.", "B": "The satellite images are not an example of the 1985 survey; they are a later measurement.", "C": "The second sentence adds new information rather than restating the first."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0004', 'HDSAT-RW-M10X-T0004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The manual claims that the sensor needs no calibration after installation. ______, the manufacturer''s own field notes describe a monthly zero-point check.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "In addition"}, {"id": "B", "text": "For instance"}, {"id": "C", "text": "However"}, {"id": "D", "text": "Accordingly"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0004', 'C', ARRAY['C']::TEXT[], '''However'' highlights the contradiction between the manual''s claim and the manufacturer''s own instructions. The other choices would wrongly frame the notes as a result, an example or an extra point.', '{"D": "''Accordingly'' would present the field notes as a consequence of the manual''s claim, which they are not.", "B": "The field notes are a conflicting document, not an example of the manual''s statement.", "A": "The two documents disagree, so an additive transition would obscure the conflict."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0005', 'HDSAT-RW-M10X-T0005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Street trees lowered afternoon surface temperatures in every block the team measured. ______, the cooling effect disappeared at night, when the canopy trapped heat near the ground.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "As a result"}, {"id": "B", "text": "On the other hand"}, {"id": "C", "text": "In the same way"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0005', 'B', ARRAY['B']::TEXT[], '''On the other hand'' introduces the opposing nighttime pattern after the daytime benefit. The other options would make the night result a consequence, an example or a parallel finding.', '{"A": "The nighttime result is not caused by the daytime cooling, so a result transition is wrong.", "D": "The nighttime measurement is not an example of afternoon cooling; it is the opposite pattern.", "C": "The two findings run in different directions, so ''In the same way'' is inaccurate."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0006', 'HDSAT-RW-M10X-T0006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The harbor''s outer wall has survived two thousand years of storms. ______, the inner basin silted up within three centuries of its construction.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Likewise"}, {"id": "B", "text": "Therefore"}, {"id": "C", "text": "For example"}, {"id": "D", "text": "Yet"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0006', 'D', ARRAY['D']::TEXT[], '''Yet'' contrasts the durable outer wall with the much shorter life of the inner basin. The other choices would wrongly present the contrast as a cause, an example or a similarity.', '{"B": "The silting does not follow from the wall''s survival, so a causal transition is wrong.", "C": "The fate of the inner basin is not an illustration of the outer wall''s durability.", "A": "The two outcomes differ sharply, so ''Likewise'' would misrepresent them."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0007', 'HDSAT-RW-M10X-T0007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Colonies with young queens produced more honey in the first season. ______, those same colonies were far more likely to swarm the following spring.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Because of this"}, {"id": "B", "text": "Equally"}, {"id": "C", "text": "For instance"}, {"id": "D", "text": "Still"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0007', 'D', ARRAY['D']::TEXT[], '''Still'' concedes the early advantage while introducing a later drawback. The other options would treat swarming as a result, an example or an equivalent benefit.', '{"A": "The swarming is a drawback that accompanies the gain, not a consequence of it.", "C": "The swarming statistic is not an example of honey production.", "B": "The two results are different in kind, so ''Equally'' would overstate their similarity."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0008', 'HDSAT-RW-M10X-T0008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The telescope''s mirror was polished to a tolerance of a few nanometers. ______, its first images were blurred by a defect in the mounting, not in the glass.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Even so"}, {"id": "B", "text": "In addition"}, {"id": "C", "text": "As a result"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0008', 'A', ARRAY['A']::TEXT[], '''Even so'' concedes that the mirror was made precisely and then reports a failure elsewhere. The other transitions would wrongly link the blurring to the polishing or treat it as an added advantage.', '{"C": "The blurred images were caused by the mounting, not by the polishing, so ''As a result'' is wrong.", "D": "The defect is not an example of precise polishing; it is a separate problem.", "B": "The second sentence reports a problem, so adding it as a further benefit misreads it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0009', 'HDSAT-RW-M10X-T0009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Membership at the city''s science museum rose sharply after the new wing opened. ______, donations to its education fund declined over the same period.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For instance"}, {"id": "B", "text": "Consequently"}, {"id": "C", "text": "Nevertheless"}, {"id": "D", "text": "Similarly"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0009', 'C', ARRAY['C']::TEXT[], '''Nevertheless'' contrasts the membership increase with the simultaneous decline in donations. The other choices would present the decline as a result, an example or a parallel trend.', '{"B": "The decline in donations is not a consequence of rising membership, so ''Consequently'' is wrong.", "A": "The donation figure is not an example of membership growth.", "D": "The two trends move in opposite directions, so ''Similarly'' is inaccurate."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0010', 'HDSAT-RW-M10X-T0010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Participants who napped for twenty minutes recalled more words the next morning. ______, their reaction times on a separate task were no better than those of the control group.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For example"}, {"id": "B", "text": "Therefore"}, {"id": "C", "text": "Moreover"}, {"id": "D", "text": "However"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0010', 'D', ARRAY['D']::TEXT[], '''However'' marks the limit of the nap''s benefit: memory improved while reaction time did not. The other options would wrongly present that limit as a consequence, an example or an additional gain.', '{"B": "The lack of improvement in reaction time is not caused by the better recall, so ''Therefore'' is wrong.", "A": "The reaction-time result is a different measure, not an example of recall.", "C": "The second result limits the first, so an additive transition would overstate the benefit."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0011', 'HDSAT-RW-M10X-T0011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The river restoration removed the concrete banks and replanted native sedges. ______, fish counts in the restored reach have barely changed in five years.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Yet"}, {"id": "B", "text": "In addition"}, {"id": "C", "text": "For example"}, {"id": "D", "text": "Thus"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0011', 'A', ARRAY['A']::TEXT[], '''Yet'' signals the gap between the restoration effort and the disappointing fish counts. The other transitions would treat the outcome as a consequence, an example or an extra benefit.', '{"D": "The unchanged fish counts do not follow from the restoration work, so ''Thus'' is wrong.", "C": "The fish counts are an outcome, not an example of the replanting.", "B": "The second sentence reports a disappointing result, so adding it as another gain misreads it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0012', 'HDSAT-RW-M10X-T0012', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The coral nursery raised fragments on rope frames suspended above the seabed. ______, it kept a second set of fragments in cooler water to test heat tolerance.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Therefore"}, {"id": "B", "text": "In addition"}, {"id": "C", "text": "For instance"}, {"id": "D", "text": "However"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0012', 'B', ARRAY['B']::TEXT[], '''In addition'' adds the second, parallel experiment to the first. The other choices would wrongly frame it as a contrast, a result or an example.', '{"D": "The second activity does not contradict the first, so ''However'' is wrong.", "A": "The cooler-water set was a deliberate comparison, not a consequence of the frames.", "C": "The second set is a separate experiment rather than an example of the rope frames."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0013', 'HDSAT-RW-M10X-T0013', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The typeface was designed for readers with low vision. ______, its numerals were drawn to stay distinct at very small sizes.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Nevertheless"}, {"id": "B", "text": "By contrast"}, {"id": "C", "text": "Moreover"}, {"id": "D", "text": "Therefore"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0013', 'C', ARRAY['C']::TEXT[], '''Moreover'' adds a second feature that supports the same design goal. The other options would wrongly suggest contrast, cause or opposition between the two choices.', '{"A": "The numeral design does not contradict the overall design goal, so ''Nevertheless'' is wrong.", "D": "Distinct numerals are part of the design, not a consequence of it.", "B": "The two features work together, so ''By contrast'' would invent a conflict."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0014', 'HDSAT-RW-M10X-T0014', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The vineyard''s soil sensors report moisture every fifteen minutes. ______, a weather station on the ridge records wind speed and humidity.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "However"}, {"id": "B", "text": "For instance"}, {"id": "C", "text": "In addition"}, {"id": "D", "text": "So"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0014', 'C', ARRAY['C']::TEXT[], '''In addition'' adds the weather station to the list of instruments monitoring the vineyard. The other choices would wrongly imply contrast, causation or exemplification.', '{"A": "The two instruments do not conflict, so ''However'' is wrong.", "D": "The weather station was installed alongside the sensors, not because of them.", "B": "The weather station is a separate instrument, not an example of a soil sensor."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0015', 'HDSAT-RW-M10X-T0015', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Satellite tags revealed that the birds crossed the desert in a single night. ______, ground observers found that the same birds rested for two days before continuing.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For example"}, {"id": "B", "text": "Meanwhile"}, {"id": "C", "text": "Nevertheless"}, {"id": "D", "text": "Therefore"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0015', 'B', ARRAY['B']::TEXT[], '''Meanwhile'' sets the ground observation alongside the satellite finding as a parallel piece of evidence. The other transitions would wrongly suggest cause, example or concession.', '{"D": "The resting period is not a consequence of the night crossing, so ''Therefore'' is wrong.", "A": "The resting observation is not an example of the crossing.", "C": "The two findings describe different stages of the journey, not a contradiction."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0016', 'HDSAT-RW-M10X-T0016', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The kiln was fired in a reducing atmosphere to deepen the glaze. ______, each vessel was rotated a quarter turn every hour so that it would not slump.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "At the same time"}, {"id": "B", "text": "In contrast"}, {"id": "C", "text": "As a result"}, {"id": "D", "text": "For instance"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0016', 'A', ARRAY['A']::TEXT[], '''At the same time'' adds a second procedure carried out during the same firing. The other options would wrongly present it as a result, a contrast or an example.', '{"C": "The rotation was a separate precaution, not an effect of the reducing atmosphere.", "B": "The two procedures were both part of the firing, so they do not contrast.", "D": "The rotation is not an example of a firing atmosphere."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0017', 'HDSAT-RW-M10X-T0017', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The new cycle lanes cut injury rates along the avenue by half. ______, secure parking at six transit stations gave riders a place to leave their bikes overnight.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Therefore"}, {"id": "B", "text": "In addition"}, {"id": "C", "text": "However"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0017', 'B', ARRAY['B']::TEXT[], '''In addition'' presents the parking as another measure introduced alongside the lanes. The other choices would wrongly make it a contrast, a result or an illustration.', '{"C": "The parking does not contradict the safety improvement, so ''However'' is wrong.", "A": "The parking was a separate investment, not a consequence of the lanes.", "D": "The parking is a complementary measure, not an example of a cycle lane."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0018', 'HDSAT-RW-M10X-T0018', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The archive digitised its photographic collection at high resolution. ______, it recorded an oral history interview with every surviving photographer.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Additionally"}, {"id": "B", "text": "As a result"}, {"id": "C", "text": "For example"}, {"id": "D", "text": "However"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0018', 'A', ARRAY['A']::TEXT[], '''Additionally'' adds a second preservation project to the first. The other transitions would wrongly frame the interviews as a contrast, a consequence or an example.', '{"D": "The interviews do not conflict with the digitisation, so ''However'' is wrong.", "B": "The interviews were a separate project, not an effect of scanning the photographs.", "C": "The interviews are not an example of digitisation; they are a different record."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0019', 'HDSAT-RW-M10X-T0019', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Thin-film panels can be printed onto flexible backing. ______, they perform well in diffuse light, which makes them useful on overcast days.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Moreover"}, {"id": "B", "text": "Consequently"}, {"id": "C", "text": "For example"}, {"id": "D", "text": "Nevertheless"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0019', 'A', ARRAY['A']::TEXT[], '''Moreover'' adds a second advantage of thin-film panels. The other choices would wrongly present it as a contrast, a consequence or an example.', '{"D": "The second sentence supports the first rather than contradicting it.", "B": "The performance in diffuse light is a property of the panels, not a result of the flexible backing.", "C": "The performance claim is not an example of printing on flexible backing."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0020', 'HDSAT-RW-M10X-T0020', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The bridge''s expansion joints had not been replaced in thirty years. ______, engineers closed two lanes for emergency repairs after the first hard freeze.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "However"}, {"id": "B", "text": "As a result"}, {"id": "C", "text": "For example"}, {"id": "D", "text": "In addition"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0020', 'B', ARRAY['B']::TEXT[], '''As a result'' links the overdue maintenance to the emergency closures that followed. The other transitions would wrongly present the outcome as a contrast, an example or an extra point.', '{"A": "The repairs were a consequence of the worn joints, not a contrast to them.", "C": "The lane closures are an outcome, not an example of the joints.", "D": "The closures are not an additional benefit, so ''In addition'' misreads the relation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0021', 'HDSAT-RW-M10X-T0021', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The hatchery lost its water supply when the intake pipe froze. ______, staff moved forty thousand juvenile salmon to a backup tank within six hours.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Nevertheless"}, {"id": "B", "text": "Meanwhile"}, {"id": "C", "text": "For instance"}, {"id": "D", "text": "Consequently"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0021', 'D', ARRAY['D']::TEXT[], '''Consequently'' marks the staff''s rapid move as the result of losing the water supply. The other options would wrongly suggest concession, example or mere simultaneity.', '{"A": "The move was a direct response to the lost supply, not a concession to it.", "C": "The move was an action taken after the failure, not an example of the failure.", "B": "The two events are causally linked, so ''Meanwhile'' would hide the connection."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0022', 'HDSAT-RW-M10X-T0022', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Fewer than one in five respondents had ever used the emergency app. ______, the county redesigned the interface and advertised it through libraries.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "However"}, {"id": "B", "text": "Therefore"}, {"id": "C", "text": "For example"}, {"id": "D", "text": "Likewise"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0022', 'B', ARRAY['B']::TEXT[], '''Therefore'' presents the redesign as the county''s response to low use. The other choices would wrongly frame it as a contrast, an example or a parallel situation.', '{"A": "The redesign responds to the low use rather than opposing it.", "C": "The redesign is a response, not an example of low use.", "D": "The two actions are cause and response, not parallel cases."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0023', 'HDSAT-RW-M10X-T0023', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The manuscript had been stored in a damp cellar for decades. ______, conservators spent four months removing mould from the margins.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For example"}, {"id": "B", "text": "In contrast"}, {"id": "C", "text": "As a result"}, {"id": "D", "text": "In addition"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0023', 'C', ARRAY['C']::TEXT[], '''As a result'' connects the damp storage to the months of conservation work. The other transitions would wrongly suggest contrast, exemplification or addition.', '{"B": "The mould removal was caused by the damp storage, not a contrast to it.", "A": "The conservation work is an outcome, not an example of cellar storage.", "D": "The second sentence reports necessary repair, not an added benefit."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0024', 'HDSAT-RW-M10X-T0024', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The turbine blades accumulated ice faster than the de-icing system could clear it. ______, operators shut the array down during the storm.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "So"}, {"id": "B", "text": "For example"}, {"id": "C", "text": "Yet"}, {"id": "D", "text": "Likewise"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0024', 'A', ARRAY['A']::TEXT[], '''So'' presents the shutdown as the consequence of ice building faster than the system could remove it. The other options would wrongly signal contrast, example or similarity.', '{"C": "The shutdown was caused by the icing, not an exception to it.", "B": "Shutting down is a response, not an example of ice accumulation.", "D": "The shutdown is a consequence, not a parallel case."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0025', 'HDSAT-RW-M10X-T0025', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Demand for the clinic''s evening appointments doubled in a year. ______, it hired two more nurses and extended its hours to nine.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For instance"}, {"id": "B", "text": "In response"}, {"id": "C", "text": "By contrast"}, {"id": "D", "text": "Similarly"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0025', 'B', ARRAY['B']::TEXT[], '''In response'' frames the hiring and longer hours as the clinic''s answer to rising demand. The other choices would wrongly suggest contrast, example or similarity.', '{"C": "The new hires answer the demand rather than contrast with it.", "A": "The new hires are a response, not an example of demand.", "D": "The measures are a reaction to the demand, not a parallel trend."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0026', 'HDSAT-RW-M10X-T0026', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The seed vault''s cooling system failed during a regional power cut. ______, staff drilled a second, independent generator the following summer.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For example"}, {"id": "B", "text": "However"}, {"id": "C", "text": "Equally"}, {"id": "D", "text": "As a result"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0026', 'D', ARRAY['D']::TEXT[], '''As a result'' links the cooling failure to the decision to install an independent generator. The other options would misstate the relation as contrast, example or equivalence.', '{"B": "The new generator was a consequence of the failure, not a contrast to it.", "A": "The generator is a response, not an example of the power cut.", "C": "The two events are cause and remedy, not equivalent cases."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0027', 'HDSAT-RW-M10X-T0027', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The software update removed an outdated security certificate. ______, several older devices could no longer connect to the network.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For example"}, {"id": "B", "text": "Nevertheless"}, {"id": "C", "text": "Consequently"}, {"id": "D", "text": "In addition"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0027', 'C', ARRAY['C']::TEXT[], '''Consequently'' marks the lost connections as the result of removing the certificate. The other transitions would wrongly suggest concession, exemplification or addition.', '{"B": "The connection failures were caused by the removed certificate, not a concession.", "A": "The failures are an outcome, not an example of the update.", "D": "The failures are a side effect, not an extra benefit."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0028', 'HDSAT-RW-M10X-T0028', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Several deep-sea species survive on chemicals rather than sunlight. ______, tube worms at hydrothermal vents feed through bacteria that oxidise hydrogen sulfide.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Therefore"}, {"id": "B", "text": "In addition"}, {"id": "C", "text": "However"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0028', 'D', ARRAY['D']::TEXT[], '''For example'' introduces the tube worms as a specific case of chemical-based survival. The other options would wrongly signal contrast, causation or a separate additional point.', '{"C": "The tube worms illustrate the claim rather than contradicting it.", "A": "The tube worms are an illustration, not a consequence of the general statement.", "B": "The example supports a claim already made, so ''In addition'' misses the relation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0029', 'HDSAT-RW-M10X-T0029', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'Early maps of the region placed rivers that later surveys could not find. ______, a 1740 chart shows a channel running west from the delta that no modern map includes.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "By contrast"}, {"id": "B", "text": "As a result"}, {"id": "C", "text": "Moreover"}, {"id": "D", "text": "For instance"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0029', 'D', ARRAY['D']::TEXT[], '''For instance'' offers the 1740 chart as a concrete case of a mapped river that later surveys could not find. The other choices would misread it as a result, a contrast or an addition.', '{"B": "The 1740 chart is an illustration, not a consequence of the general claim.", "A": "The chart supports the claim about early maps rather than opposing it.", "C": "The chart is an example of the claim, not a new and separate point."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0030', 'HDSAT-RW-M10X-T0030', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'Some plants defend themselves chemically against grazing insects. ______, tomato leaves release a compound that slows caterpillar growth when the leaves are damaged.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Thus"}, {"id": "B", "text": "For example"}, {"id": "C", "text": "Similarly"}, {"id": "D", "text": "However"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0030', 'B', ARRAY['B']::TEXT[], '''For example'' presents the tomato''s chemical response as a specific instance of plant defence. The other transitions would wrongly suggest contrast, cause or similarity.', '{"D": "The tomato case supports the general claim rather than contradicting it.", "A": "The tomato case is an instance, not a consequence of the general statement.", "C": "The tomato case is offered as evidence, not as a parallel separate claim."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0031', 'HDSAT-RW-M10X-T0031', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The orchestra''s archive contains instruments that fell out of use centuries ago. ______, a curved cornet from 1790 sits in the collection beside a serpent and a lute.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For instance"}, {"id": "B", "text": "In addition"}, {"id": "C", "text": "Nevertheless"}, {"id": "D", "text": "Therefore"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0031', 'A', ARRAY['A']::TEXT[], '''For instance'' introduces the cornet, serpent and lute as examples of obsolete instruments in the archive. The other options would wrongly signal cause, concession or addition.', '{"D": "The instruments are evidence for the claim, not a consequence of it.", "C": "The instruments support the claim rather than conceding anything against it.", "B": "The instruments are examples of the claim, not a separate added topic."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0032', 'HDSAT-RW-M10X-T0032', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'Cities have begun to cool public spaces with reflective surfaces. ______, a pilot project in Los Angeles repainted school roofs and recorded a five-degree drop in playground temperature.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Likewise"}, {"id": "B", "text": "Consequently"}, {"id": "C", "text": "However"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0032', 'D', ARRAY['D']::TEXT[], '''For example'' introduces the Los Angeles pilot as a specific case of cooling with reflective surfaces. The other choices would misstate it as contrast, consequence or a separate parallel.', '{"C": "The Los Angeles project supports the general claim instead of opposing it.", "B": "The project is an illustration, not a result of the general trend.", "A": "The project is a specific case, not a parallel separate trend."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0033', 'HDSAT-RW-M10X-T0033', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The survey found that students rarely used the library''s online tutorials. ______, only eleven percent of first-year students opened one during their first term.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For example"}, {"id": "B", "text": "In contrast"}, {"id": "C", "text": "Therefore"}, {"id": "D", "text": "Moreover"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0033', 'A', ARRAY['A']::TEXT[], '''For example'' presents the eleven-percent figure as evidence of the low use. The other transitions would wrongly frame the statistic as a consequence, a contrast or an addition.', '{"C": "The statistic supports the finding rather than following from it as a separate result.", "B": "The statistic confirms the finding instead of opposing it.", "D": "The statistic is evidence for the claim, not an additional unrelated point."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0034', 'HDSAT-RW-M10X-T0034', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'Many desert animals avoid the heat by being active at night. ______, the kangaroo rat leaves its burrow only after the sand has cooled.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Still"}, {"id": "B", "text": "In addition"}, {"id": "C", "text": "For instance"}, {"id": "D", "text": "As a result"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0034', 'C', ARRAY['C']::TEXT[], '''For instance'' gives the kangaroo rat as a concrete example of nighttime activity. The other options would wrongly signal concession, causation or addition.', '{"A": "The kangaroo rat supports the general claim rather than conceding a point.", "D": "The behaviour is an example, not a consequence of the general statement.", "B": "The example illustrates the claim instead of adding a new topic."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0035', 'HDSAT-RW-M10X-T0035', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The coating is expensive to apply and requires a trained crew. ______, it has already paid for itself in reduced repainting on two bridges.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For example"}, {"id": "B", "text": "Therefore"}, {"id": "C", "text": "In addition"}, {"id": "D", "text": "Even so"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0035', 'D', ARRAY['D']::TEXT[], '''Even so'' concedes the high cost and then reports the savings that outweigh it. The other choices would wrongly present the payback as a result, an example or another cost.', '{"B": "The payback is a counterweight to the cost, not a consequence of it.", "A": "The payback is not an example of the coating''s expense.", "C": "The second sentence offsets the first rather than adding a similar point."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0036', 'HDSAT-RW-M10X-T0036', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The theory explains most of the observed data. ______, it cannot account for the unusually warm winters of the 1930s.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Nevertheless"}, {"id": "B", "text": "Consequently"}, {"id": "C", "text": "Moreover"}, {"id": "D", "text": "For instance"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0036', 'A', ARRAY['A']::TEXT[], '''Nevertheless'' introduces a limitation that stands against the theory''s broad success. The other transitions would wrongly present the exception as a result, an example or additional support.', '{"B": "The unexplained winters are a limitation, not a consequence of the theory''s success.", "D": "The warm winters are a counterexample, not an example of the theory''s explanatory power.", "C": "The second sentence limits the theory rather than adding support for it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0037', 'HDSAT-RW-M10X-T0037', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The first edition sold fewer than five hundred copies. ______, it is now regarded as the founding text of the field.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Similarly"}, {"id": "B", "text": "As a result"}, {"id": "C", "text": "Nonetheless"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0037', 'C', ARRAY['C']::TEXT[], '''Nonetheless'' contrasts the book''s poor initial sales with its later standing. The other choices would wrongly suggest cause, example or similarity.', '{"B": "The later reputation was not caused by the poor sales.", "D": "The later reputation is a reversal, not an example of weak sales.", "A": "The two facts point in opposite directions, so ''Similarly'' is wrong."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0038', 'HDSAT-RW-M10X-T0038', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The trail is closed to vehicles and has no cell reception. ______, it draws more than ten thousand hikers each summer.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Therefore"}, {"id": "B", "text": "Still"}, {"id": "C", "text": "In addition"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0038', 'B', ARRAY['B']::TEXT[], '''Still'' concedes the trail''s drawbacks and then reports its popularity. The other options would wrongly present the visitors as a result, an example or an additional drawback.', '{"A": "The popularity is not a consequence of the trail''s isolation.", "D": "The visitor number is a contrast to the drawbacks, not an example of them.", "C": "The second sentence sets a benefit against the drawbacks rather than adding a similar one."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0039', 'HDSAT-RW-M10X-T0039', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The new schedule reduced waiting times at the clinic. ______, some patients found the earlier appointments easier to reach by bus.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Likewise"}, {"id": "B", "text": "Thus"}, {"id": "C", "text": "For instance"}, {"id": "D", "text": "That said"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0039', 'D', ARRAY['D']::TEXT[], '''That said'' concedes a drawback after reporting the improvement. The other choices would wrongly suggest cause, exemplification or similarity.', '{"B": "The bus complaint is a qualification, not a consequence of shorter waits.", "C": "The complaint is a drawback, not an example of reduced waiting.", "A": "The complaint qualifies the improvement rather than paralleling it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0040', 'HDSAT-RW-M10X-T0040', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The archive''s catalogue is available online in full. ______, most of its photographs can be seen only by visiting in person.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Therefore"}, {"id": "B", "text": "For example"}, {"id": "C", "text": "In addition"}, {"id": "D", "text": "However"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0040', 'D', ARRAY['D']::TEXT[], '''However'' marks the limit on what the online catalogue offers. The other options would wrongly present the restriction as a result, an example or an added convenience.', '{"A": "The limited access is not a consequence of the online catalogue.", "B": "The photographs are not an example of the catalogue; they are a separate restriction.", "C": "The second sentence limits the first rather than adding a similar benefit."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0041', 'HDSAT-RW-M10X-T0041', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The crew pumped the flooded hold dry and replaced the damaged frames. ______, they applied three coats of primer before the hull was returned to the water.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "For example"}, {"id": "B", "text": "Next"}, {"id": "C", "text": "Therefore"}, {"id": "D", "text": "However"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0041', 'B', ARRAY['B']::TEXT[], '''Next'' places the priming after the pumping and frame replacement in the repair sequence. The other choices would wrongly signal contrast, example or causation.', '{"D": "The priming continues the repair sequence rather than contrasting with it.", "A": "The priming is a later step, not an example of pumping the hold.", "C": "The priming is the next step in the work, not a consequence of the frames."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0042', 'HDSAT-RW-M10X-T0042', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The experimenter recorded the baseline reading for ten minutes. ______, she introduced the tracer dye and continued sampling every thirty seconds.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "In addition"}, {"id": "B", "text": "Then"}, {"id": "C", "text": "Nevertheless"}, {"id": "D", "text": "For instance"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0042', 'B', ARRAY['B']::TEXT[], '''Then'' marks the dye injection as the step that followed the baseline reading. The other transitions would wrongly signal concession, example or addition.', '{"C": "The dye step is the next action, not a concession to the baseline reading.", "D": "The dye step is not an example of a baseline reading.", "A": "The dye step follows in time rather than adding a separate point."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0043', 'HDSAT-RW-M10X-T0043', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The first phase mapped the cave''s upper passages. ______, the second phase surveyed the flooded chambers below.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Likewise"}, {"id": "B", "text": "However"}, {"id": "C", "text": "For example"}, {"id": "D", "text": "Afterward"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0043', 'D', ARRAY['D']::TEXT[], '''Afterward'' places the second survey after the first mapping phase. The other choices would wrongly signal contrast, example or a parallel comparison.', '{"B": "The second phase continues the work rather than opposing the first.", "C": "The flooded chambers are not an example of the upper passages.", "A": "The phases are sequential, not parallel independent cases."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0044', 'HDSAT-RW-M10X-T0044', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The committee published its draft for public comment in March. ______, it held six hearings across the county before revising the text.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "In contrast"}, {"id": "B", "text": "Nevertheless"}, {"id": "C", "text": "For instance"}, {"id": "D", "text": "Subsequently"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0044', 'D', ARRAY['D']::TEXT[], '''Subsequently'' places the hearings after the draft''s publication in the process. The other options would wrongly suggest concession, exemplification or contrast.', '{"B": "The hearings followed the draft rather than conceding anything against it.", "C": "The hearings are a later stage, not an example of the draft.", "A": "The hearings continue the process rather than contrasting with it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0045', 'HDSAT-RW-M10X-T0045', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The seedlings were hardened in a shaded frame for two weeks. ______, they were transplanted into the field once the last frost had passed.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "However"}, {"id": "B", "text": "Later"}, {"id": "C", "text": "Therefore"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0045', 'B', ARRAY['B']::TEXT[], '''Later'' marks transplanting as the stage that followed hardening. The other choices would wrongly signal contrast, example or cause.', '{"A": "Transplanting continues the sequence rather than contrasting with hardening.", "D": "Transplanting is the next stage, not an example of hardening.", "C": "Transplanting follows in time, not because of the hardening."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0046', 'HDSAT-RW-M10X-T0046', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The tribunal heard closing arguments in the morning. ______, it issued a written ruling the following week.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "After that"}, {"id": "B", "text": "By contrast"}, {"id": "C", "text": "In addition"}, {"id": "D", "text": "For instance"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0046', 'A', ARRAY['A']::TEXT[], '''After that'' places the written ruling after the closing arguments. The other transitions would wrongly signal contrast, example or addition.', '{"B": "The ruling followed the arguments rather than contrasting with them.", "D": "The ruling is a later step, not an example of the arguments.", "C": "The ruling comes next in time, not as an additional separate point."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0047', 'HDSAT-RW-M10X-T0047', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The drug lowered blood pressure in the trial''s first month. ______, the effect had largely disappeared by the end of the year.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Therefore"}, {"id": "B", "text": "However"}, {"id": "C", "text": "In addition"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0047', 'B', ARRAY['B']::TEXT[], '''However'' contrasts the early benefit with its later disappearance. The other choices would wrongly treat the loss of effect as a result, an example or an added benefit.', '{"A": "The fading effect does not follow from the early success as a consequence.", "D": "The later result is not an example of the early reduction.", "C": "The second finding undercuts the first, so an additive transition is wrong."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0048', 'HDSAT-RW-M10X-T0048', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The survey asked how often residents visited the park. ______, it also recorded how they travelled there.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "However"}, {"id": "B", "text": "In addition"}, {"id": "C", "text": "Therefore"}, {"id": "D", "text": "For instance"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0048', 'B', ARRAY['B']::TEXT[], '''In addition'' adds the travel question to the survey''s scope. The other options would wrongly signal contrast, cause or exemplification.', '{"A": "The travel question does not contradict the first question.", "C": "The travel question was part of the design, not a consequence of the first.", "D": "The travel question is a second item, not an example of the first."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0049', 'HDSAT-RW-M10X-T0049', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The ferry''s engine failed midway across the strait. ______, passengers waited four hours for a relief vessel.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Likewise"}, {"id": "B", "text": "For example"}, {"id": "C", "text": "However"}, {"id": "D", "text": "As a result"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0049', 'D', ARRAY['D']::TEXT[], '''As a result'' links the engine failure to the long wait for a relief vessel. The other transitions would wrongly suggest contrast, example or similarity.', '{"C": "The wait was caused by the engine failure, not a contrast to it.", "B": "The wait is an outcome, not an example of the failure.", "A": "The wait is a consequence, not a parallel case."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0050', 'HDSAT-RW-M10X-T0050', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'Some fungi form partnerships with the roots of a single tree species. ______, the birch bolete attaches only to birches.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Therefore"}, {"id": "B", "text": "However"}, {"id": "C", "text": "For example"}, {"id": "D", "text": "In addition"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0050', 'C', ARRAY['C']::TEXT[], '''For example'' introduces the birch bolete as a specific case of a fungus tied to one tree species. The other choices would wrongly signal contrast, cause or addition.', '{"B": "The bolete supports the general claim rather than opposing it.", "A": "The bolete is an instance, not a consequence of the general statement.", "D": "The bolete illustrates the claim instead of adding a new topic."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0051', 'HDSAT-RW-M10X-T0051', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Medium', 'multiple_choice', 'The proposal would save the city money over twenty years. ______, its upfront cost exceeds the current budget.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Even so"}, {"id": "B", "text": "For instance"}, {"id": "C", "text": "Therefore"}, {"id": "D", "text": "In addition"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0051', 'A', ARRAY['A']::TEXT[], '''Even so'' concedes the long-term savings and then sets the immediate cost against them. The other options would wrongly present the cost as a result, an example or another saving.', '{"C": "The high upfront cost resists the savings rather than following from them.", "B": "The cost is a drawback, not an example of the savings.", "D": "The second sentence offsets the first rather than adding a similar point."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0052', 'HDSAT-RW-M10X-T0052', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'Workers removed the old track bed and graded the surface. ______, they laid the new rails in sections during overnight closures.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Next"}, {"id": "B", "text": "Therefore"}, {"id": "C", "text": "However"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0052', 'A', ARRAY['A']::TEXT[], '''Next'' places the rail laying after removing the track bed and grading. The other transitions would wrongly signal contrast, example or cause.', '{"C": "Laying the rails continues the sequence rather than contrasting with it.", "D": "Laying the rails is a later stage, not an example of grading.", "B": "Laying the rails follows in time, not because of the grading."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0053', 'HDSAT-RW-M10X-T0053', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The novel was dismissed by reviewers when it appeared. ______, it has never gone out of print.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Similarly"}, {"id": "B", "text": "Yet"}, {"id": "C", "text": "Therefore"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0053', 'B', ARRAY['B']::TEXT[], '''Yet'' contrasts the early dismissal with the novel''s enduring availability. The other choices would wrongly suggest cause, example or similarity.', '{"C": "The book''s lasting availability was not caused by the dismissive reviews.", "D": "The long print run is a reversal, not an example of the reviews.", "A": "The two facts point in opposite directions, so ''Similarly'' is wrong."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-T0054', 'HDSAT-RW-M10X-T0054', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Transitions', 'Easy', 'multiple_choice', 'The orchard''s irrigation line was damaged by construction. ______, the grower lost most of the young trees that summer.', 'Which choice completes the text with the most logical transition?', '[{"id": "A", "text": "Equally"}, {"id": "B", "text": "However"}, {"id": "C", "text": "Consequently"}, {"id": "D", "text": "For example"}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-T0054', 'C', ARRAY['C']::TEXT[], '''Consequently'' marks the lost trees as the result of the damaged irrigation line. The other choices would wrongly signal contrast, example or equivalence.', '{"B": "The loss was caused by the damaged line, not a contrast to it.", "D": "The loss is an outcome, not an example of the damage.", "A": "The loss is a consequence, not an equivalent event."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0000a', 'HDSAT-RW-M10X-P0000a', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'In 2012 the Voyager 1 spacecraft crossed the heliopause, the boundary where the sun''s wind gives way to the interstellar medium. Mission planners had expected a sharp crossing: a sudden drop in solar particles and a simultaneous jump in galactic cosmic rays. The actual data arrived in stages, with the particle drop preceding the magnetic-field change by months. Because no single instrument marked a clean edge, the team had to argue that the crossing was real and had happened earlier than the magnetic readings alone suggested.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The heliopause turned out to be a boundary that no spacecraft can cross."}, {"id": "B", "text": "Voyager 1''s crossing of the heliopause was established from several instruments whose signals did not agree at the same moment."}, {"id": "C", "text": "Voyager 1 stopped transmitting data before it could leave the solar system."}, {"id": "D", "text": "Solar particles and galactic cosmic rays always change at the same instant."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0000a', 'B', ARRAY['B']::TEXT[], 'The passage is about interpreting evidence: because the particle and magnetic signals changed months apart, scientists could not point to one instrument as proof and had to build the case from the combined record.', '{"C": "The text describes data arriving in stages, not a loss of contact.", "A": "The passage says the crossing happened; it is about how the team recognized it.", "D": "The mismatch in timing is the central problem the text describes."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0001', 'HDSAT-RW-M10X-P0001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The copper blade of Otzi the Iceman''s axe contains trace elements that match ore deposits in central Italy, hundreds of kilometers south of where his body was found in the Alps. That result unsettled the assumption that early Alpine communities used only local metal. It also pointed to trade in finished objects rather than raw material alone: the blade''s chemistry is southern, while the yew handle came from a tree that grew near the discovery site.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Alpine communities had no copper tools before Otzi''s lifetime."}, {"id": "B", "text": "Otzi mined and smelted the copper for his axe near the site where he died."}, {"id": "C", "text": "The axe was assembled entirely from materials gathered in one valley."}, {"id": "D", "text": "The axe combines materials from distant and local sources, evidence of long-distance exchange in finished tools."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0001', 'D', ARRAY['D']::TEXT[], 'The key detail is the split origin: southern copper and a local yew handle. That combination is what supports the claim about exchange of finished tools across long distances.', '{"B": "The blade''s chemistry matches Italian ore, not local deposits.", "A": "The text discusses where the metal came from, not when copper first reached the Alps.", "C": "The handle is local but the blade is not, which contradicts a single-valley origin."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0002', 'HDSAT-RW-M10X-P0002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'White-crowned sparrows in neighboring valleys sing subtly different songs, and young birds learn the version they hear where they settle. When researchers swapped eggs between populations, the fledglings sang the dialect of the adults that raised them, not the one associated with their birthplace. The differences are small enough that a casual listener would miss them, yet females respond more strongly to their own dialect, which keeps the populations from blending into a single song type.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The dialects are so different that the birds cannot recognize one another."}, {"id": "B", "text": "Females prefer songs from valleys other than their own."}, {"id": "C", "text": "Sparrow dialects are inherited genetically from the mother."}, {"id": "D", "text": "Song dialects are learned from surrounding adults, and female preferences help keep them distinct."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0002', 'D', ARRAY['D']::TEXT[], 'The passage connects learning to preference: fledglings adopt the local song from their caretakers, and females favoring that song is what maintains the boundary between populations.', '{"C": "The egg-swap result shows the dialect follows the adults that raised the bird.", "B": "The text says females respond more strongly to their own dialect.", "A": "The differences are described as small and easy to miss."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0003', 'HDSAT-RW-M10X-P0003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'The earliest writing from Mesopotamia is mostly accounting. Tablets from the late fourth millennium BCE record quantities of grain, livestock and labor, often with a symbol for the commodity beside a number. Narrative and poetry appear only later, once scribes had adapted the same signs to represent sounds as well as objects. Writing, in other words, did not begin as literature that happened to keep records; it began as a record-keeping technology that later made literature possible.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Mesopotamian writing developed first for accounting and was later extended to literary uses."}, {"id": "B", "text": "The earliest tablets contain no numbers, only pictures of animals."}, {"id": "C", "text": "Mesopotamian scribes used writing mainly to preserve poems and myths."}, {"id": "D", "text": "Literature and accounting appeared at exactly the same time."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0003', 'A', ARRAY['A']::TEXT[], 'The final sentence states the reversal directly: record keeping came first, and the same sign system was later adapted to sound-based writing and literature.', '{"C": "The text says the earliest writing is mostly accounting, with literature later.", "B": "The tablets record quantities beside commodity symbols.", "D": "The passage explicitly separates the two periods."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0004', 'HDSAT-RW-M10X-P0004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Air trapped in Antarctic ice cores preserves samples of the atmosphere stretching back hundreds of thousands of years. Researchers crush a slice of core in a sealed chamber, release the bubbles and measure the gases. Because the bubbles close off at different depths, a single core yields a sequence rather than a snapshot. The record shows carbon dioxide rising and falling with glacial cycles, though the ice cannot by itself establish which change came first.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Ice cores preserve a dated sequence of ancient air, but they do not settle the direction of cause and effect."}, {"id": "B", "text": "The carbon dioxide record proves that temperature changes always follow gas changes."}, {"id": "C", "text": "Each ice core provides a single sample of the atmosphere from one year."}, {"id": "D", "text": "Ice cores contain liquid water that can be analyzed directly."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0004', 'A', ARRAY['A']::TEXT[], 'The passage describes both the method''s strength, a long sequence, and its limit, the inability to order cause and effect from the gas record alone.', '{"D": "The air is in bubbles, released by crushing the ice, not stored as liquid.", "C": "The text says bubbles close at different depths, producing a sequence.", "B": "The passage says the ice cannot establish which change came first."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0005', 'HDSAT-RW-M10X-P0005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'The Antikythera mechanism, recovered from a first-century BCE shipwreck, contains at least thirty interlocking bronze gears. Early scholars assumed such gearing belonged to a later era, but the device''s tooth counts match the ratios needed to model the moon''s uneven motion. A reconstruction using those counts reproduces the positions of the sun and moon across decades, suggesting that Greek artisans had built a compact predictive model centuries before comparable gearing appears elsewhere.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The shipwreck contained a complete set of identical bronze devices."}, {"id": "B", "text": "The gear counts prove that Greek artisans copied a later Roman design."}, {"id": "C", "text": "The mechanism was a decorative object with no astronomical function."}, {"id": "D", "text": "The mechanism''s gear ratios show that sophisticated astronomical gearing existed earlier than scholars once assumed."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0005', 'D', ARRAY['D']::TEXT[], 'The tooth counts are the evidence: they encode the moon''s uneven motion, and a reconstruction works, which is why the device pushes the history of complex gearing backward.', '{"C": "The reconstruction reproduces sun and moon positions, so the device is functional.", "A": "The text describes one mechanism, not a set of identical copies.", "B": "The passage places the device before comparable gearing elsewhere, not after it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0006', 'HDSAT-RW-M10X-P0006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Before the eleventh century, many natural philosophers explained vision as a ray leaving the eye and feeling the object. Ibn al-Haytham argued instead that light travels from objects to the eye, and he tested the idea with a dark room that admitted a narrow beam. The image on the far wall appeared inverted, which a ray from the eye could not easily explain. His account was not immediately accepted everywhere, but it moved the study of light toward experiment rather than pure argument.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Ibn al-Haytham''s experiments supported light entering the eye and helped shift optics toward empirical testing."}, {"id": "B", "text": "Ibn al-Haytham proved that the eye emits rays that illuminate objects."}, {"id": "C", "text": "He argued that vision cannot be studied through experiment."}, {"id": "D", "text": "His dark-room experiment was rejected because the image appeared upright."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0006', 'A', ARRAY['A']::TEXT[], 'The passage pairs a specific experimental result, the inverted image, with a broader change in method, from argument toward experiment.', '{"B": "He argued the opposite: light travels from objects to the eye.", "D": "The image appeared inverted, which supported his account.", "C": "The text says his work moved the field toward experiment."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0007', 'HDSAT-RW-M10X-P0007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Restoring a prairie is not simply a matter of stopping the plow. Many grassland plants survive only as seed in the soil, and that reserve dwindles after decades of row crops. Restoration teams therefore sow hand-collected seed from nearby remnants, sometimes over several seasons, and they mow or burn in the first years to keep fast-growing weeds from shading the seedlings. The result is a plant community that resembles the original more closely than a single sowing of commercial seed mix would.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Commercial seed mixes reproduce prairie remnants more faithfully than local seed does."}, {"id": "B", "text": "Mowing and burning are used to destroy the seedlings that restoration teams sow."}, {"id": "C", "text": "Prairie plants cannot survive in soil that was once used for row crops."}, {"id": "D", "text": "Successful prairie restoration depends on local seed and several years of active management, not merely on retiring farmland."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0007', 'D', ARRAY['D']::TEXT[], 'The opening rejects the simple view, and the rest explains what restoration actually requires: a local seed source, repeated sowing and early weed control.', '{"A": "The text says local hand-collected seed produces a closer match.", "C": "The passage describes soil seed reserves dwindling, not the impossibility of growth.", "B": "Those treatments keep weeds from shading the seedlings; they do not kill the seedlings."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0008', 'HDSAT-RW-M10X-P0008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Octopuses living in cold water edit their RNA far more extensively than their warm-water relatives do. The edits change proteins involved in nerve signaling, and the pattern shifts when the animals are moved to colder tanks. Because RNA editing does not alter the underlying DNA, the response can be temporary. Researchers argue that this flexibility lets the animals tune their nervous systems to temperature without waiting for a favorable mutation to spread through a population.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "RNA editing permanently rewrites the genetic code of every cell in the octopus."}, {"id": "B", "text": "Temperature has no measurable effect on the proteins used in nerve signaling."}, {"id": "C", "text": "Extensive RNA editing lets some octopuses adjust nerve proteins to cold without changing their DNA."}, {"id": "D", "text": "Cold-water octopuses carry permanent DNA mutations that warm-water octopuses lack."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0008', 'C', ARRAY['C']::TEXT[], 'The passage contrasts a fast, reversible RNA response with the slow process of mutation, and that contrast is the main claim.', '{"D": "The text says the edits do not alter the underlying DNA.", "A": "The response can be temporary and does not change the DNA sequence.", "B": "The edits change proteins involved in nerve signaling."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0009', 'HDSAT-RW-M10X-P0009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Before standard containers, loading a cargo ship meant handling thousands of separate crates, sacks and barrels. The work was slow, theft was common and a vessel could spend as many days in port as at sea. Standard steel boxes changed the economics less by speeding up the ship than by moving the cost to the dock, where cranes could transfer a box in minutes. Ports that invested in cranes and deep berths flourished; older harbors with narrow wharves declined.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Containerization lowered shipping costs mainly by transforming dock work, which reshaped which ports prospered."}, {"id": "B", "text": "Older harbors with narrow wharves gained the most from container traffic."}, {"id": "C", "text": "Standard boxes eliminated theft by sealing cargo inside steel."}, {"id": "D", "text": "Containerization made ships faster than earlier cargo vessels."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0009', 'A', ARRAY['A']::TEXT[], 'The central claim is a shift in where the cost sat: cranes and berths, not ship speed, produced the savings, and that is why some ports grew and others shrank.', '{"D": "The text says the gain came less from ship speed than from dock handling.", "C": "Theft is mentioned as a problem before containers, not as something containers eliminated.", "B": "The passage says those older harbors declined."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0010', 'HDSAT-RW-M10X-P0010', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Lichens are not plants but partnerships between a fungus and algae or cyanobacteria. The fungus provides structure and absorbs minerals; the photosynthetic partner supplies sugars. Because lichens take up nutrients directly from the air, they accumulate pollutants that plants with roots may filter out. Surveys that map lichen diversity therefore double as rough maps of air quality: sensitive species disappear first near industry, while a few tolerant species spread.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "All lichen species tolerate pollution equally well."}, {"id": "B", "text": "Lichens are single organisms that draw nutrients through roots."}, {"id": "C", "text": "Because lichens absorb nutrients from air, their diversity can indicate air quality."}, {"id": "D", "text": "Lichens produce sugars without a photosynthetic partner."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0010', 'C', ARRAY['C']::TEXT[], 'The passage builds from what a lichen is to why that matters: direct air absorption makes the partnership a passive sampler, so diversity becomes an indicator.', '{"B": "The text describes a partnership and absorption from the air, not roots.", "A": "It says sensitive species disappear first while tolerant ones spread.", "D": "The photosynthetic partner supplies the sugars."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0011', 'HDSAT-RW-M10X-P0011', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Roman glassmakers used two different alkali sources. Along the Mediterranean coast they relied on natron, a mineral deposit rich in soda; inland, where natron was scarce, they used ash from burned plants. The two recipes produce glass with different trace elements and different working properties. Analysis of museum collections shows that the recipes were not simply local preferences: vessels made with plant ash appear in coastal cities and natron glass appears far inland, which indicates that glass itself, not just raw material, was traded.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The two recipes produced glass too similar to tell apart chemically."}, {"id": "B", "text": "Roman glassmakers used natron exclusively because plant ash was unavailable."}, {"id": "C", "text": "Plant-ash glass is found only in the regions where the plants grew."}, {"id": "D", "text": "Two distinct Roman glass recipes can be traced through trace elements, showing that finished glass traveled between regions."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0011', 'D', ARRAY['D']::TEXT[], 'The chemistry distinguishes the recipes, and the mismatches between recipe and location are what support the conclusion about trade in finished vessels.', '{"B": "The text says inland makers used plant ash when natron was scarce.", "A": "The recipes produce different trace elements and working properties.", "C": "Plant-ash vessels appear in coastal cities, which is the evidence for trade."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0012', 'HDSAT-RW-M10X-P0012', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'The Great Dismal Swamp, straddling the Virginia-North Carolina border, sheltered communities of self-emancipated Black people from the seventeenth century into the nineteenth. The swamp was difficult for outsiders to cross but offered solid islands, fresh water and game. Archaeological work has recovered handmade pottery, hearths and the remains of cabins on those islands, showing that the communities were permanent settlements rather than temporary camps. Their isolation was not complete: goods such as iron tools reached them through networks of trade and kinship.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The swamp communities were short-lived camps that left no material trace."}, {"id": "B", "text": "The residents lived in complete isolation and had no contact with outsiders."}, {"id": "C", "text": "The swamp was easy to cross, which made it a poor place for refuge."}, {"id": "D", "text": "Archaeological evidence shows that maroon communities built lasting settlements in the swamp while remaining connected to outside trade."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0012', 'D', ARRAY['D']::TEXT[], 'The main idea combines two findings that pull in different directions: permanence on the islands and continuing ties to the wider economy.', '{"A": "The text cites pottery, hearths and cabin remains as evidence of permanent settlement.", "B": "Iron tools reached them through trade and kinship networks.", "C": "The passage says the swamp was difficult for outsiders to cross."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0013', 'HDSAT-RW-M10X-P0013', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Mistletoe is often described as a parasite, but its role in a woodland is more complicated. It draws water and minerals from its host, yet its berries feed birds, its dense clusters shelter nests, and the nutrients it drops enrich the soil beneath the tree. Plots with moderate mistletoe loads often support more bird species than plots without it. Heavy infestations can still weaken a tree, so the relationship depends on how much mistletoe is present.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "The plant neither takes nor gives anything to its ecosystem."}, {"id": "B", "text": "Birds avoid areas where mistletoe is present."}, {"id": "C", "text": "Mistletoe is harmless to its host at every level of infestation."}, {"id": "D", "text": "Mistletoe can benefit a woodland at moderate levels even though it takes resources from its host tree."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0013', 'D', ARRAY['D']::TEXT[], 'The passage qualifies the label ''parasite'' by describing benefits that depend on abundance, which is the central point.', '{"C": "The text says heavy infestations can weaken a tree.", "B": "Its berries feed birds and its clusters shelter nests.", "A": "It draws water and minerals and also enriches soil and supports wildlife."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0014', 'HDSAT-RW-M10X-P0014', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'The moon raises tides on the side of Earth facing it and, because the planet is rotating faster than the moon orbits, also on the far side. The resulting bulge is carried slightly ahead of the moon by friction. That offset exerts a torque that slows Earth''s rotation and pushes the moon into a wider orbit. The effect is small each year, but over geological time it has lengthened the day and increased the distance between Earth and the moon.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Tidal friction gradually slows Earth''s rotation and widens the moon''s orbit."}, {"id": "B", "text": "The moon''s gravity has no effect on the length of an Earth day."}, {"id": "C", "text": "Tides occur only on the side of Earth that faces the moon."}, {"id": "D", "text": "Earth''s rotation is speeding up, which pulls the moon closer."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0014', 'A', ARRAY['A']::TEXT[], 'The causal chain is the main idea: friction offsets the bulge, the offset creates torque, and the torque changes both Earth''s spin and the moon''s distance.', '{"B": "The text says the day has lengthened over geological time.", "D": "The torque slows rotation and pushes the moon outward.", "C": "The passage describes bulges on both the near and far sides."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0015', 'HDSAT-RW-M10X-P0015', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Papermakers in Europe began adding watermarks in the thirteenth century, pressing a wire design into the wet pulp so the sheet dried thinner in those places. The mark is visible only when the paper is held to light, which made it useful for identifying a mill rather than decorating a page. Because molds wore out and designs changed, dated documents can sometimes be matched to a mill''s known watermark sequence. The method is not exact: a mill might use an old mold alongside a new one for years.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Every watermark can be tied to a single year of production."}, {"id": "B", "text": "Papermakers stopped using molds once watermarks were introduced."}, {"id": "C", "text": "Watermarks were painted onto finished pages as decoration."}, {"id": "D", "text": "Watermarks can help date and place paper, but overlapping mold use limits how precise the method is."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0015', 'D', ARRAY['D']::TEXT[], 'The passage presents a dating technique and then states its limitation, and that combination is the main point.', '{"C": "The design was pressed into wet pulp with a wire and shows only in transmitted light.", "A": "The text warns that a mill could use an old mold alongside a new one for years.", "B": "The mold is the tool that carries the watermark."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0016', 'HDSAT-RW-M10X-P0016', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Vultures routinely feed on carcasses that would sicken most other animals. Their stomach acid is unusually strong, and their gut community is dominated by bacteria that tolerate it. Experiments that fed vultures infected meat found that the acid and the resident microbes together reduced the dose of pathogens the birds shed. The service is not glamorous, but it slows the spread of disease from dead animals to living ones.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Vultures avoid infected meat because their stomach acid is weak."}, {"id": "B", "text": "Their gut bacteria are the only defense against infected meat."}, {"id": "C", "text": "The birds spread pathogens more widely than other scavengers do."}, {"id": "D", "text": "Vultures'' acidic stomachs and gut bacteria let them dispose of carcasses while limiting pathogen spread."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0016', 'D', ARRAY['D']::TEXT[], 'The main idea links the birds'' physiology to an ecosystem service: strong acid plus tolerant microbes lower the pathogens they release.', '{"A": "The acid is unusually strong, and they feed on such carcasses routinely.", "C": "The passage says they reduce the dose of pathogens shed.", "B": "The text credits the acid and the microbes together."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0017', 'HDSAT-RW-M10X-P0017', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Roman roads are often admired for their straightness, but their drainage may have mattered more. Builders dug side ditches, raised the carriageway on layers of gravel and sand, and crowned the surface so water ran off. In wet climates those choices kept the foundation from softening under traffic. A road that looked impressive but held water would have failed in its first spring, so the invisible layers beneath the paving were as important as the paving itself.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Roman engineers avoided crownings because they weakened the surface."}, {"id": "B", "text": "The durability of Roman roads depended heavily on drainage and foundation layers that are easy to overlook."}, {"id": "C", "text": "The visible paving stones were the only part of a road that mattered."}, {"id": "D", "text": "Roman roads were built without ditches because the climate was dry."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0017', 'B', ARRAY['B']::TEXT[], 'The passage redirects attention from the famous straight paving to the drainage system and foundation that kept the road usable.', '{"D": "The text describes side ditches and a wet climate.", "C": "The passage credits the hidden layers beneath the paving.", "A": "The surface was crowned so water would run off."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0018', 'HDSAT-RW-M10X-P0018', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'Some pine cones stay sealed for years and open only after a fire heats them. The trait, called serotiny, keeps seed safe in the canopy until a burn clears competing vegetation and returns nutrients to the soil. But serotiny carries a risk: if fires are suppressed for too long, the cones may rot or the trees may die before releasing seed. Managers who reintroduce prescribed fire therefore have to consider not only how hot a burn is but how long it has been since the last one.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Serotinous cones open on their own without any heat."}, {"id": "B", "text": "Fire always destroys the seeds stored in a pine canopy."}, {"id": "C", "text": "Serotiny depends on fire, but long fire-free periods can undermine the strategy, complicating prescribed burns."}, {"id": "D", "text": "Prescribed burns are unnecessary where serotinous pines grow."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0018', 'C', ARRAY['C']::TEXT[], 'The passage explains both the benefit of serotiny and its dependence on fire frequency, which is why managers must think about timing as well as intensity.', '{"A": "The text says the cones open only after a fire heats them.", "B": "Heat releases the seed; the passage does not say fire destroys it.", "D": "Managers reintroducing fire must weigh burn heat and time since the last burn."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0019', 'HDSAT-RW-M10X-P0019', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Before the 1970s, deaf children in Nicaragua had little contact with one another and used isolated home signs. When a school for deaf students opened and brought them together, a shared sign language emerged within a few years, with its own grammar and vocabulary. Younger children who entered later learned the system from older students and then regularized it further, producing more consistent verb agreement. The case suggests that a community of learners, not a single inventor, can generate a full language.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Later generations made the language less consistent than the first version."}, {"id": "B", "text": "Deaf children in Nicaragua used a written language before the school opened."}, {"id": "C", "text": "Nicaraguan Sign Language arose from a community of deaf learners and became more systematic across generations."}, {"id": "D", "text": "The language was invented by a single teacher and taught unchanged to students."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0019', 'C', ARRAY['C']::TEXT[], 'The main claim is collective creation and generational refinement, supported by the sequence from home signs to a shared grammar.', '{"D": "The text says a community generated it, not one inventor.", "B": "The passage describes isolated home signs, not a shared written language.", "A": "Later students regularized the system further."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0020', 'HDSAT-RW-M10X-P0020', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Hard', 'multiple_choice', 'Ammonite shells are divided by walls called septa, and the line where a septum meets the shell is the suture. Early ammonites have simple, gently curved sutures; later forms have deeply folded ones. The folds increase the surface area where the septum attaches, which may strengthen the shell against pressure. Because the complex sutures appear in lineages that also show other signs of deeper-water life, paleontologists debate whether the strength was the cause of the change or a consequence of it.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Complex ammonite sutures may have strengthened the shell, but their role is still debated."}, {"id": "B", "text": "Suture complexity decreased steadily as ammonites evolved."}, {"id": "C", "text": "Paleontologists agree that folded sutures had no function."}, {"id": "D", "text": "The septa are the outer surface of the shell rather than internal walls."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0020', 'A', ARRAY['A']::TEXT[], 'The passage presents a functional hypothesis and then the uncertainty around it, which is the main point.', '{"B": "The text says later forms have deeply folded sutures.", "C": "The debate is about cause and consequence, not about whether the folds mattered.", "D": "Septa are described as walls dividing the shell."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0021', 'HDSAT-RW-M10X-P0021', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Easy', 'multiple_choice', 'Coffee grown under a canopy of shade trees supports more bird species than coffee grown in open sun. The shade trees provide fruit and insects, and the layered foliage offers nesting sites that a low, uniform coffee field lacks. Yields per hectare can be lower in shade, however, and farmers who switch to full sun often do so for short-term volume. Certification programs try to make shade-grown coffee pay by connecting growers to buyers who value the habitat.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "Shade-grown coffee always produces higher yields per hectare."}, {"id": "B", "text": "Shade-grown coffee benefits bird habitat but can cost yield, so certification aims to reward growers for keeping shade."}, {"id": "C", "text": "Certification programs require farmers to remove shade trees."}, {"id": "D", "text": "Sun-grown coffee supports more bird species than shade-grown coffee."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0021', 'B', ARRAY['B']::TEXT[], 'The main idea balances an ecological benefit with an economic cost and names certification as the attempt to reconcile them.', '{"D": "The text says the opposite: shade supports more species.", "A": "The passage says yields can be lower in shade.", "C": "Certification connects growers who keep shade with willing buyers."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0022', 'HDSAT-RW-M10X-P0022', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Dung beetles roll balls of manure away from a pile and travel in a straight line once they leave. In an outdoor arena, beetles fitted with tiny hats that blocked the sky rolled in circles, while beetles with clear hats kept a steady course. When the sky was overcast, the beetles could not hold a line. Indoors, under a simulated star field, they oriented correctly even without the moon.', 'The text most strongly suggests that dung beetles navigate by', '[{"id": "A", "text": "remembering landmarks they passed on earlier trips."}, {"id": "B", "text": "following the smell of the manure pile behind them."}, {"id": "C", "text": "relying on the position of the sun during the day."}, {"id": "D", "text": "using the pattern of the night sky, including stars, as a compass."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0022', 'D', ARRAY['D']::TEXT[], 'The hat experiments isolate the sky as the cue: blocking it breaks orientation, and a star field restores it, so the beetles read celestial patterns.', '{"B": "The beetles travel in a straight line away from the pile, which scent would not provide.", "C": "The tests used a night sky and a simulated star field, not the sun.", "A": "Blocking the sky disrupted them, which points to celestial rather than landmark cues."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0023', 'HDSAT-RW-M10X-P0023', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'The oldest known domestic cat burials lie in Cyprus, an island with no native wildcats. The cats were buried with people around 9,500 years ago. Later Egyptian art shows cats near grain stores, and genetic studies link Near Eastern wildcats to modern domestic cats. The animal''s rise is usually explained not by affection alone but by a practical arrangement: stored grain attracted rodents, rodents attracted wildcats, and people tolerated the cats that kept the stores clear.', 'The text most strongly suggests that the relationship between people and cats began because', '[{"id": "A", "text": "cats were domesticated to serve as household companions first."}, {"id": "B", "text": "cats helped control rodents around stored food."}, {"id": "C", "text": "Egyptians shipped cats to islands to control snakes."}, {"id": "D", "text": "people brought wildcats to Cyprus for religious rituals."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0023', 'B', ARRAY['B']::TEXT[], 'The passage lays out a chain from grain to rodents to wildcats to tolerance, which supports a practical origin rather than companionship or ritual.', '{"D": "Religion is not offered as the cause; the grain-and-rodent chain is.", "A": "The text says the arrangement was practical, not affection first.", "C": "Snakes are not mentioned, and the Cyprus burial predates the Egyptian material."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0024', 'HDSAT-RW-M10X-P0024', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Antarctic fish survive in water cold enough to freeze the blood of most species. Their blood contains antifreeze glycoproteins that bind to small ice crystals and prevent them from growing. The proteins do not melt ice that has already formed; they stop further growth. Fish that lack the proteins survive only in shallower, less stable water, and species with the highest concentrations are found in the coldest, most ice-prone habitats.', 'The text most strongly suggests that the antifreeze proteins are most useful when', '[{"id": "A", "text": "a fish needs to melt a large block of ice inside its body."}, {"id": "B", "text": "ice crystals have begun to form and would otherwise keep growing."}, {"id": "C", "text": "the water is warm enough that no ice forms at all."}, {"id": "D", "text": "the fish is swimming in shallow water with stable temperatures."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0024', 'B', ARRAY['B']::TEXT[], 'The passage defines the proteins'' action as preventing growth, not melting, and links higher concentrations to icier habitats.', '{"C": "Warm water needs no protection from growing crystals.", "A": "The text says the proteins stop growth but do not melt existing ice.", "D": "Fish without the proteins survive in shallower, less stable water, so that is the low-need case."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0025', 'HDSAT-RW-M10X-P0025', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Many ancient clay tablets survive because they were accidentally fired. A palace or archive that burned left its tablets baked hard, while tablets stored in buildings that never caught fire were often lost to moisture and reuse. Archaeologists therefore recover a biased sample: the written records we can read come disproportionately from places that suffered a destructive fire, not from the quiet archives where scribes may have worked most steadily.', 'The text most strongly suggests that the surviving tablets', '[{"id": "A", "text": "were deliberately fired by scribes to make them permanent."}, {"id": "B", "text": "may overrepresent records from sites that burned rather than routine archives."}, {"id": "C", "text": "are a random sample of all the tablets that were written."}, {"id": "D", "text": "come mainly from archives that were carefully preserved without fire."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0025', 'B', ARRAY['B']::TEXT[], 'The reasoning runs from preservation conditions to sampling bias: fire preserves tablets, so burned sites are overrepresented in what scholars can read.', '{"D": "The passage says unfired tablets were often lost to moisture and reuse.", "A": "The firing is described as accidental in the cases that preserved them.", "C": "The text explicitly calls the sample biased."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0026', 'HDSAT-RW-M10X-P0026', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'A lighthouse needs a bright light, but a small flame is not enough at a distance. The Fresnel lens solved the problem by surrounding the flame with concentric rings of glass prisms that bend light into a narrow horizontal beam. Because the same light is concentrated rather than scattered, a modest flame can be seen far at sea. The lens also made lighthouses cheaper to operate, since keepers no longer needed a huge fire to reach the horizon.', 'The text most strongly suggests that the Fresnel lens improved lighthouses mainly by', '[{"id": "A", "text": "removing the need for a light source at the top of the tower."}, {"id": "B", "text": "allowing keepers to use a much larger fire."}, {"id": "C", "text": "redirecting light that would otherwise spread in many directions."}, {"id": "D", "text": "making the flame itself burn hotter and brighter."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0026', 'C', ARRAY['C']::TEXT[], 'The key phrase is ''concentrated rather than scattered'': the lens changes direction, not the amount of light produced.', '{"D": "The lens concentrates existing light; the text does not say it changes the flame.", "B": "The passage says the flame could be modest.", "A": "The flame remains; the lens surrounds it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0027', 'HDSAT-RW-M10X-P0027', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Hardwicke''s woolly bats roost inside the pitchers of a carnivorous plant. The plant digests insects that fall into its fluid, but the bats are too large to be trapped and leave droppings rich in nitrogen. Plants that host bats receive a measurable share of their nitrogen from those droppings, and they grow larger than pitchers that are kept closed. The plant is not eating the bat; it is harvesting the bat''s waste.', 'The text most strongly suggests that the relationship between the bat and the pitcher plant is', '[{"id": "A", "text": "harmful to the plant, because the bats block the pitcher''s opening."}, {"id": "B", "text": "neutral, because the bats neither help nor harm the plant."}, {"id": "C", "text": "parasitic, because the plant digests the bats it hosts."}, {"id": "D", "text": "mutually beneficial, with the plant gaining nutrients from the bat''s droppings."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0027', 'D', ARRAY['D']::TEXT[], 'The measured nitrogen gain and larger growth show a benefit to the plant, while the bat gains shelter, so the exchange is mutual.', '{"C": "The text says the bats are too large to be trapped.", "B": "Plants with bats grow larger, which indicates a benefit.", "A": "Blocking the opening is not mentioned; the plant gains nitrogen."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0028', 'HDSAT-RW-M10X-P0028', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Viking ships were driven by square sails that had to withstand salt, rain and stretching. Analysis of preserved fragments shows that the cloth was woven from wool with a high lanolin content, then rubbed with a mixture of grease and fish oil. The treatment made the fabric heavier and less porous, which kept it from flapping uselessly when wet. A sail of untreated cloth would absorb water, sag and lose the shape needed to catch wind.', 'The text most strongly suggests that the treatment applied to Viking sails', '[{"id": "A", "text": "had no effect on how the fabric behaved in rain."}, {"id": "B", "text": "helped the cloth keep a wind-catching shape when it got wet."}, {"id": "C", "text": "made the sails lighter so ships could travel faster."}, {"id": "D", "text": "removed the lanolin from the wool before weaving."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0028', 'B', ARRAY['B']::TEXT[], 'The contrast is explicit: treated cloth stays less porous, while untreated cloth sags and loses shape in water.', '{"C": "The text says the treatment made the fabric heavier.", "D": "The lanolin was in the cloth, and the mixture was added afterward.", "A": "Untreated cloth is described as absorbing water and sagging, so the treatment matters."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0029', 'HDSAT-RW-M10X-P0029', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Rice paddies are often flooded, and flooded soils lack oxygen. In that environment, arsenic that is bound to iron minerals can be released into the water and taken up by the plants. Researchers found that draining a field for part of the season reduced the arsenic in the grain, but it also lowered the yield and allowed weeds to establish. Strategies that change the water regime therefore have to trade a health benefit against a loss in production.', 'The text most strongly suggests that reducing arsenic in rice is', '[{"id": "A", "text": "unrelated to the chemistry of flooded soils."}, {"id": "B", "text": "a matter of balancing health gains against costs to yield."}, {"id": "C", "text": "possible only by abandoning rice cultivation entirely."}, {"id": "D", "text": "achieved by keeping fields flooded for the whole season."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0029', 'B', ARRAY['B']::TEXT[], 'The passage presents a tradeoff: draining lowers arsenic but lowers yield, so any strategy must weigh both.', '{"C": "The text describes a partial draining strategy, not abandonment.", "D": "Flooding is what releases arsenic from iron minerals.", "A": "The passage explains the release as a chemical result of low-oxygen soil."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0030', 'HDSAT-RW-M10X-P0030', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Traditional Ethiopian injera is made from teff flour that is left to ferment for several days before baking. During fermentation, wild yeasts and bacteria produce acids and gas. The acids give the flatbread its sour taste, and the gas forms the small holes that give it a spongy texture. A batter used immediately produces a flat, dense bread. Cooks describe the waiting period as essential, not incidental.', 'The text most strongly suggests that the fermentation period is necessary because it', '[{"id": "A", "text": "prevents the bread from developing holes."}, {"id": "B", "text": "makes the batter rise without any microorganisms."}, {"id": "C", "text": "produces both the flavor and the texture of the finished bread."}, {"id": "D", "text": "removes all the yeast from the batter before baking."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0030', 'C', ARRAY['C']::TEXT[], 'The passage attributes sourness to acids and holes to gas, both produced during the wait, which is why cooks treat it as essential.', '{"D": "The text says wild yeasts and bacteria do the work during fermentation.", "B": "The gas comes from those microorganisms.", "A": "The passage says fermentation forms the holes."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0031', 'HDSAT-RW-M10X-P0031', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Elephants produce low-frequency calls that travel long distances through the ground as well as the air. In one study, elephants responded to a recorded call played through the earth even when the airborne sound was masked by wind. They also responded from farther away than the audible range of the call would predict. The animals may therefore be picking up vibrations through their feet and trunk.', 'The text most strongly suggests that elephants can', '[{"id": "A", "text": "detect calls through ground vibration at distances beyond what hearing alone would allow."}, {"id": "B", "text": "hear only calls that are louder than the wind."}, {"id": "C", "text": "communicate exclusively through airborne sound."}, {"id": "D", "text": "ignore low-frequency calls when the wind is strong."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0031', 'A', ARRAY['A']::TEXT[], 'The two results, response through the ground and response from beyond the audible range, both point to vibration as an additional channel.', '{"B": "They responded when the airborne sound was masked by wind.", "C": "The study tested ground transmission as well.", "D": "They responded despite the wind."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0032', 'HDSAT-RW-M10X-P0032', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Reef-building corals live in partnership with single-celled algae that supply them with sugars from photosynthesis. When water warms sharply, the corals expel the algae and lose their color, a condition called bleaching. A bleached coral is not dead; it can recover if the algae return. But without its partner it must rely on captured food, and if the warm period lasts too long, the coral starves.', 'The text most strongly suggests that a bleached coral survives only if', '[{"id": "A", "text": "the algae remain inside it and continue to photosynthesize."}, {"id": "B", "text": "it can regain its algae before its stored energy runs out."}, {"id": "C", "text": "the water becomes warmer for a longer period."}, {"id": "D", "text": "it stops capturing food from the water."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0032', 'B', ARRAY['B']::TEXT[], 'The passage frames bleaching as a temporary loss: recovery depends on the algae returning before starvation sets in.', '{"C": "Warmth is what drives the algae out.", "D": "The text says a bleached coral must rely on captured food.", "A": "Bleaching is the loss of the algae, so they are not still inside."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0033', 'HDSAT-RW-M10X-P0033', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Ice cores from Greenland contain layers of lead pollution that date to the height of Greek and Roman metal production. The lead arrives as fine particles carried by winds from smelting sites thousands of kilometers away. Concentrations rise and fall in step with estimated smelting activity, and they drop sharply during periods when written sources describe disruption of mining. The ice therefore records an economy that left few written accounts of its own scale.', 'The text most strongly suggests that the lead layers are useful because they', '[{"id": "A", "text": "prove that Greek and Roman miners worked in Greenland."}, {"id": "B", "text": "show that written sources about mining are always accurate."}, {"id": "C", "text": "measure the temperature of the atmosphere at the time."}, {"id": "D", "text": "provide an independent record of ancient metal production."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0033', 'D', ARRAY['D']::TEXT[], 'The value of the ice record is that it is physical evidence matching estimated activity, independent of the sparse written sources.', '{"A": "The particles were carried by wind from distant smelting sites.", "B": "The layers provide a physical record independent of written accounts.", "C": "The passage is about lead particles, not temperature."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0034', 'HDSAT-RW-M10X-P0034', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'A Japanese sword is forged from steel that is folded and hammered many times. Folding distributes impurities and evens out carbon content, but it also introduces new layers of oxide unless the smith controls the atmosphere. The visible grain on a finished blade comes from these layers and from the different carbon levels in the steel. A blade with a dramatic pattern is not necessarily stronger; the pattern records the process, not the quality of the edge.', 'The text most strongly suggests that the visible pattern on a sword', '[{"id": "A", "text": "comes from paint applied after the blade is polished."}, {"id": "B", "text": "appears only when the steel contains no carbon."}, {"id": "C", "text": "shows how the steel was worked rather than how good the blade is."}, {"id": "D", "text": "guarantees that the blade holds a sharper edge."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0034', 'C', ARRAY['C']::TEXT[], 'The final sentence explicitly separates the pattern, a record of process, from the quality of the edge.', '{"D": "The text says a dramatic pattern does not make a blade stronger.", "A": "The pattern comes from layers and carbon levels in the steel.", "B": "The steel is described as having varied carbon content."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0035', 'HDSAT-RW-M10X-P0035', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Dust devils on Mars lift fine dust from the surface and spin it upward. Rovers accumulate dust on their solar panels, which reduces the power they can generate. Engineers noticed that after a dust devil passed near a rover, the panel output rose. Cameras later recorded whirlwinds crossing the rovers'' tracks. The same process that obscures the surface also clears the instruments studying it.', 'The text most strongly suggests that dust devils', '[{"id": "A", "text": "permanently damage the panels they pass near."}, {"id": "B", "text": "can clean solar panels even as they move dust around."}, {"id": "C", "text": "occur only in regions the rovers never visit."}, {"id": "D", "text": "have no effect on the power a rover produces."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0035', 'B', ARRAY['B']::TEXT[], 'The observed rise in output after a pass, plus the recorded tracks, supports the cleaning interpretation.', '{"A": "The passage reports output rising after a pass, not damage.", "D": "Output rose, so there is an effect.", "C": "Cameras recorded whirlwinds crossing the rovers'' tracks."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0036', 'HDSAT-RW-M10X-P0036', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Bottlenose dolphins produce individually distinctive whistles. When separated, a dolphin emits its own signature whistle, and group members respond by copying it. Playback experiments show that dolphins react differently to their own signature than to unfamiliar ones. The whistle appears to function as a name: it identifies the caller and allows others to address that individual.', 'The text most strongly suggests that signature whistles', '[{"id": "A", "text": "are identical across every member of a group."}, {"id": "B", "text": "carry no information about which animal is calling."}, {"id": "C", "text": "let dolphins identify and address specific individuals."}, {"id": "D", "text": "are used only when dolphins are physically together."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0036', 'C', ARRAY['C']::TEXT[], 'Distinctiveness plus selective copying and response is what supports the name-like function.', '{"A": "The whistles are described as individually distinctive.", "D": "The text describes them being used when separated.", "B": "Group members copy a specific whistle, which identifies the caller."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0037', 'HDSAT-RW-M10X-P0037', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Bodies buried in northern European peat bogs sometimes survive for thousands of years with skin, hair and clothing intact. The bogs are cold, acidic and low in oxygen, conditions that slow the microbes responsible for decay. Tannins in the peat also preserve tissue by binding proteins. The same chemistry that keeps a body intact, however, turns the skin dark and leathery, so the remains look very different from a body preserved in dry air.', 'The text most strongly suggests that peat-bog preservation depends on', '[{"id": "A", "text": "conditions that inhibit decay while chemically altering the tissue."}, {"id": "B", "text": "warm, oxygen-rich water that speeds microbial growth."}, {"id": "C", "text": "dry air that dehydrates the body quickly."}, {"id": "D", "text": "removal of tannins from the surrounding peat."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0037', 'A', ARRAY['A']::TEXT[], 'The passage names the preservative conditions and then the side effect, so preservation is a combination of slowed decay and chemical change.', '{"B": "The bog is cold and low in oxygen, which slows microbes.", "C": "The bodies are in wet peat, and dry-air preservation is offered as a contrast.", "D": "Tannins are part of what preserves the tissue."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0038', 'HDSAT-RW-M10X-P0038', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Wind turbines kill bats, often in late summer when bats migrate. The deaths are not mostly from collisions with blades: pressure changes near the blade tips can damage the animals'' lungs. Operators found that slowing the blades at low wind speeds, when power output is small, reduced bat deaths substantially. The curtailment costs some electricity, but far less than shutting the turbines down entirely would.', 'The text most strongly suggests that the curtailment strategy works because', '[{"id": "A", "text": "bat deaths are caused mainly by collisions with towers."}, {"id": "B", "text": "it increases the pressure changes that bats avoid."}, {"id": "C", "text": "it stops the turbines from turning at all during migration."}, {"id": "D", "text": "it reduces the conditions that injure bats while sacrificing little generation."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0038', 'D', ARRAY['D']::TEXT[], 'The text links the injury mechanism to blade speed and notes that the power lost is small, which explains why the tradeoff is acceptable.', '{"C": "The blades are slowed, not stopped, and only at low wind speeds.", "B": "The strategy reduces deaths, so it must reduce the harmful conditions.", "A": "The passage says the deaths are not mostly from collisions with blades."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0039', 'HDSAT-RW-M10X-P0039', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'Vampire bats feed on the blood of other animals, a diet low in usable carbohydrates. Their saliva contains a protein that prevents blood from clotting at the wound. Researchers have studied the protein as a possible treatment for stroke, where a clot blocks blood flow to the brain. The bat uses the same molecule to keep a meal flowing, a function that is useful to the animal and potentially useful to medicine.', 'The text most strongly suggests that the clotting protein in vampire bat saliva', '[{"id": "A", "text": "causes blood to clot more quickly at a wound."}, {"id": "B", "text": "has no function for the bat itself."}, {"id": "C", "text": "is useful only for digesting carbohydrates."}, {"id": "D", "text": "serves the bat''s feeding and has a potential medical use."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0039', 'D', ARRAY['D']::TEXT[], 'The passage presents one molecule with two consequences: it helps the bat feed and it suggests a treatment for clot-caused stroke.', '{"A": "The protein prevents clotting; that is what keeps the meal flowing.", "B": "It keeps the bat''s meal from clotting.", "C": "The bat''s diet is low in carbohydrates, and the protein acts on clotting."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0040', 'HDSAT-RW-M10X-P0040', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Easy', 'multiple_choice', 'Most plants form partnerships with soil fungi called mycorrhizae. The fungi extend fine threads through the soil and deliver phosphorus and water to the roots; the plant supplies sugars. Seedlings that establish the partnership early often survive drought better than seedlings without it. In heavily disturbed soil, where the fungal network has been broken up, young trees can struggle even when nutrients are added, because the delivery system itself is missing.', 'The text most strongly suggests that mycorrhizae are important because they', '[{"id": "A", "text": "compete with plant roots for phosphorus and water."}, {"id": "B", "text": "produce all of a plant''s sugars through photosynthesis."}, {"id": "C", "text": "extend a plant''s access to water and nutrients beyond its roots."}, {"id": "D", "text": "make added nutrients unnecessary in any soil."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0040', 'C', ARRAY['C']::TEXT[], 'The delivery system is the key idea: the fungal threads reach resources the roots cannot, and that is why their loss matters.', '{"B": "The plant supplies the sugars; the fungus delivers water and phosphorus.", "A": "The fungi deliver those resources to the roots.", "D": "The passage says seedlings struggle in disturbed soil even when nutrients are added."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0041', 'HDSAT-RW-M10X-P0041', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Hard', 'multiple_choice', 'Felt hats in the nineteenth century were made from animal fur treated with mercury compounds. Workers in hat factories breathed mercury vapor and developed tremors, irritability and confusion. The symptoms were so closely associated with the trade that the phrase ''mad as a hatter'' entered common speech. Later regulations removed mercury from the process, and the occupational illness declined.', 'The text most strongly suggests that the illness among hatmakers was caused by', '[{"id": "A", "text": "a genetic condition common among hatmakers."}, {"id": "B", "text": "the shape of the hats they wore while working."}, {"id": "C", "text": "exposure to mercury during felt production."}, {"id": "D", "text": "the fur itself rather than any chemical treatment."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0041', 'C', ARRAY['C']::TEXT[], 'The passage ties the symptoms to mercury vapor and notes that removing mercury reduced the illness, which supports the causal claim.', '{"B": "The text names mercury vapor as the exposure and describes the symptoms.", "A": "No genetic explanation is offered.", "D": "The fur was treated with mercury compounds, which is the stated hazard."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0042', 'HDSAT-RW-M10X-P0042', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Ecologists once assumed that a stable ecosystem returns to its original state after a disturbance. That assumption held for many grasslands, where grazing pressure eased and the same grasses regrew. But in some shrublands, a single fire can shift the system into a different stable state dominated by invasive grasses, and the original shrubs do not return even after decades. Stability, it turns out, can mean persistence of a new arrangement rather than recovery of the old one.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It lists the causes of wildfires in order of importance."}, {"id": "B", "text": "It presents an assumption, offers a case that complicates it, and revises the concept."}, {"id": "C", "text": "It compares two grassland species without drawing a general conclusion."}, {"id": "D", "text": "It describes a single experiment and then rejects all of its findings."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0042', 'B', ARRAY['B']::TEXT[], 'The movement is from a general assumption to a counterexample to a revised definition, which is the structure the key names.', '{"D": "The text uses several cases, not one experiment, and retains the idea of stability.", "A": "Fire is one example; the passage is not a ranking of causes.", "C": "The comparison is between ecosystem states, and the passage does draw a conclusion."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0043', 'HDSAT-RW-M10X-P0043', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The first surveys of deep-sea animals relied on dredges that scraped the bottom and brought up whatever survived the trip. Many fragile animals were destroyed before they reached the deck, so early catalogs described a fauna that seemed tougher and sparser than it was. Modern submersibles with gentle collection arms and sealed containers have revealed delicate gelatinous creatures that were previously invisible to science. The history of the field is therefore partly a history of its tools.', 'Which choice best describes the function of the final sentence?', '[{"id": "A", "text": "It questions whether deep-sea animals exist at all."}, {"id": "B", "text": "It draws a general conclusion from the contrast between older and newer collection methods."}, {"id": "C", "text": "It lists the technical specifications of modern submersibles."}, {"id": "D", "text": "It introduces a new species that the rest of the passage will describe."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0043', 'B', ARRAY['B']::TEXT[], 'After contrasting destructive dredges with gentle submersibles, the last sentence generalizes: what scientists can see depends on how they collect.', '{"D": "No new species is introduced after it.", "A": "The passage affirms the fauna and explains why it looked sparse.", "C": "Specifications appear earlier, and the last sentence is a conclusion."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0044', 'HDSAT-RW-M10X-P0044', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'In the 1850s, a young woman named Mary Anning''s fossil finds had already changed what naturalists understood about extinct marine reptiles, though she was not allowed into the learned societies that debated them. She collected along the cliffs near Lyme Regis, prepared the specimens and sold them to museums. Her correspondents sometimes repeated her observations without naming her. The passage of her knowledge into the scientific record was therefore both essential and largely uncredited.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes a person''s contributions and then explains why they were underrepresented in the record."}, {"id": "B", "text": "It narrates a single day in the life of a fossil hunter."}, {"id": "C", "text": "It argues that fossil collecting was unimportant to natural history."}, {"id": "D", "text": "It compares two museums and their acquisition policies."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0044', 'A', ARRAY['A']::TEXT[], 'The first sentences establish her work, and the last explains the gap between its importance and the credit it received.', '{"C": "The passage says her finds changed understanding.", "B": "The text spans decades of work, not one day.", "D": "Museums are mentioned as buyers, not compared."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0045', 'HDSAT-RW-M10X-P0045', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Two Bronze Age shipwrecks off the same coast carried cargoes of copper ingots. One wreck held ingots from a single source, stacked in neat rows. The other held ingots from at least three sources, mixed with personal possessions and repair materials. Archaeologists read the first as a state-organized shipment and the second as a voyage that accumulated goods at several ports. The difference in cargo composition, rather than the age of the ships, is what supports the contrast.', 'Which choice best describes the function of the final sentence?', '[{"id": "A", "text": "It introduces a third shipwreck that changes the argument."}, {"id": "B", "text": "It identifies the evidence that the interpretation depends on."}, {"id": "C", "text": "It concedes that the two cargoes are actually identical."}, {"id": "D", "text": "It explains how copper ingots were smelted."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0045', 'B', ARRAY['B']::TEXT[], 'The sentence points back to the cargo composition and says that is the basis for reading the wrecks differently, so its function is evidential.', '{"A": "No third wreck appears.", "C": "The cargoes differ, and the sentence emphasizes that difference.", "D": "Smelting is not discussed."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0046', 'HDSAT-RW-M10X-P0046', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'Urban trees cool streets in two ways. They block sunlight before it reaches pavement, and they release water vapor that carries heat away. A city that plants only small ornamental trees gains little shade, so the first benefit is limited. A city that plants large-canopy trees but waters them poorly may lose the second. The design lesson is that species choice and maintenance have to be planned together.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It explains two mechanisms, notes the limits of each, and draws a practical conclusion."}, {"id": "B", "text": "It describes a single mechanism and ignores its limitations."}, {"id": "C", "text": "It argues that urban trees have no cooling effect."}, {"id": "D", "text": "It ranks tree species by cost without discussing shade."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0046', 'A', ARRAY['A']::TEXT[], 'The passage sets out two cooling pathways, gives a failure case for each, and ends with the planning implication.', '{"B": "Two mechanisms are named, and their limits are discussed.", "C": "The passage says trees cool streets.", "D": "Cost is not the basis of comparison."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0047', 'HDSAT-RW-M10X-P0047', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Salt was once valuable enough to serve as pay, and the English word ''salary'' is often said to derive from it. The etymology is shakier than the story suggests: ''salary'' comes from the Latin for salt, but the link to soldiers'' rations is disputed. What is well documented is the scale of the salt trade, which moved the mineral from coastal pans to inland markets along routes that shaped settlement. The vivid story survives partly because the economic reality was genuinely important.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It traces the word ''salary'' to a Germanic root."}, {"id": "B", "text": "It argues that salt had no economic value in the past."}, {"id": "C", "text": "It qualifies a popular claim and then redirects attention to the documented importance of the trade."}, {"id": "D", "text": "It proves that Roman soldiers were paid in salt."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0047', 'C', ARRAY['C']::TEXT[], 'The structure is a qualification followed by a replacement emphasis: the etymology is uncertain, but the trade''s scale is not.', '{"D": "The passage calls the link to rations disputed.", "B": "It says the salt trade was genuinely important.", "A": "The text connects the word to Latin."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0048', 'HDSAT-RW-M10X-P0048', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'A lichen is a partnership, but is it a mutualism in which both partners benefit equally? In some pairs, the fungus appears to control the relationship so tightly that the algal partner cannot reproduce independently. In others, the alga can survive alone and the fungus cannot. Rather than ask whether lichens are mutualistic in general, researchers now ask under what conditions the balance shifts toward one partner or the other.', 'Which choice best describes the function of the first sentence?', '[{"id": "A", "text": "It answers the question that the passage then supports."}, {"id": "B", "text": "It presents a fact unrelated to the rest of the paragraph."}, {"id": "C", "text": "It poses the question the rest of the passage refines and complicates."}, {"id": "D", "text": "It defines a term that is never used again."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0048', 'C', ARRAY['C']::TEXT[], 'The opening question frames the discussion, and the passage replaces a general answer with a conditional one.', '{"A": "The passage complicates the question rather than settling it.", "D": "The term ''mutualism'' is central to the discussion.", "B": "The rest of the paragraph directly addresses the question it raises."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0049', 'HDSAT-RW-M10X-P0049', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A hummingbird''s heart can beat more than a thousand times a minute during flight. At night, some species enter torpor: their body temperature falls, their heart rate drops and their metabolism slows. The change conserves energy when flowers are scarce and the bird cannot feed. Torpor is not sleep. The bird is unresponsive and can take hours to return to normal, but it can survive a cold night that would otherwise exhaust its reserves.', 'Which choice best describes the function of the sentence ''Torpor is not sleep''?', '[{"id": "A", "text": "It proves that hummingbirds never sleep."}, {"id": "B", "text": "It introduces a new topic that the passage does not develop."}, {"id": "C", "text": "It compares two species of hummingbird."}, {"id": "D", "text": "It corrects a likely misconception before the passage explains what torpor does."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0049', 'D', ARRAY['D']::TEXT[], 'The short sentence blocks a natural assumption and prepares for the description of unresponsiveness and slow recovery.', '{"B": "The next sentences continue to describe torpor.", "A": "The passage does not claim the birds never sleep, only that torpor differs from it.", "C": "No second species is introduced there."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0050', 'HDSAT-RW-M10X-P0050', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Think of a termite mound as a lung. The structure is riddled with channels, and as wind passes over the surface, pressure differences draw stale air out and fresh air in. The comparison is imperfect, because a lung contracts and a mound does not. But it captures the essential feature: ventilation here is driven by the shape of the structure and the movement of air outside it, not by a pump inside.', 'Which choice best describes the function of the analogy to a lung?', '[{"id": "A", "text": "It helps explain a ventilation process while the passage acknowledges where the comparison fails."}, {"id": "B", "text": "It replaces the need for any explanation of airflow."}, {"id": "C", "text": "It suggests that the mound contracts like a muscle."}, {"id": "D", "text": "It proves that termites have lungs inside the mound."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0050', 'A', ARRAY['A']::TEXT[], 'The passage uses the comparison to convey airflow and immediately notes its limit, so the analogy is explanatory and qualified.', '{"D": "The mound is compared to a lung, not said to contain one.", "C": "The passage explicitly says the mound does not contract.", "B": "The analogy illustrates the explanation rather than replacing it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0051', 'HDSAT-RW-M10X-P0051', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Coral reefs cover a small fraction of the ocean floor yet support a large share of marine species. That disproportion is often explained by the reef''s physical complexity: branching and mounding corals create crevices, ledges and surfaces at many scales. A flat limestone bottom in the same water holds far fewer species. When a storm flattens a reef, diversity can fall even though the water chemistry has not changed. Structure, not just location, appears to do much of the work.', 'Which choice best describes the function of the storm example?', '[{"id": "A", "text": "It shows that storms improve reef diversity."}, {"id": "B", "text": "It introduces a cause unrelated to the physical complexity argument."}, {"id": "C", "text": "It supports the claim that physical structure itself affects species diversity."}, {"id": "D", "text": "It proves that water chemistry is the only factor that matters."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0051', 'C', ARRAY['C']::TEXT[], 'The storm removes structure while holding chemistry constant, so the drop in diversity isolates structure as the cause.', '{"A": "Diversity falls after a storm flattens a reef.", "B": "The storm removes structure, which is exactly the argument''s variable.", "D": "The passage says chemistry did not change while diversity did."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0052', 'HDSAT-RW-M10X-P0052', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'Two explanations dominate for the collapse of the Maya city of Copan. One blames drought: rainfall records from nearby lake sediments show dry periods that coincide with the city''s decline. The other blames deforestation and soil exhaustion, pointing to eroded slopes and declining crop yields. A recent synthesis argues that the two are not rivals, since a dry spell would have hit a landscape already stripped of trees especially hard. The debate has shifted from choosing between causes to understanding how they interacted.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It defends one explanation and dismisses the other as impossible."}, {"id": "B", "text": "It argues that the city''s collapse cannot be explained."}, {"id": "C", "text": "It presents competing explanations and then describes an attempt to combine them."}, {"id": "D", "text": "It narrates the founding of Copan in chronological order."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0052', 'C', ARRAY['C']::TEXT[], 'The passage sets two hypotheses side by side and ends with a synthesis that reframes the debate as interaction.', '{"A": "The synthesis treats them as interacting rather than choosing one.", "D": "The passage concerns the collapse, not the founding.", "B": "It describes an emerging explanation, not an impossibility."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0053', 'HDSAT-RW-M10X-P0053', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'The word ''mammal'' comes from the Latin for breast, a reference to the glands that define the group. Naming a whole class of animals after one feature is unusual, and the choice reflects the eighteenth-century habit of classifying by visible anatomy. Modern biologists still use the name even though they now define mammals by a suite of traits, including hair and a particular jaw joint. The label survives because it is convenient, not because one feature tells the whole story.', 'Which choice best describes the function of the parenthetical reference to Latin in the first sentence?', '[{"id": "A", "text": "It shows that Latin is necessary for modern biology."}, {"id": "B", "text": "It explains the origin of a term that the passage goes on to question."}, {"id": "C", "text": "It offers the main evidence for the passage''s argument about anatomy."}, {"id": "D", "text": "It corrects a mistake in the classification of mammals."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0053', 'B', ARRAY['B']::TEXT[], 'The etymology is background for the term, and the passage then argues that the name is a convenience rather than a full definition.', '{"C": "The argument is about classification habits, not about the language.", "D": "The passage does not say the classification is a mistake, only that the name highlights one trait.", "A": "The passage says modern definitions use several traits, not Latin."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0054', 'HDSAT-RW-M10X-P0054', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A gardener notices that a tomato plant wilted in the afternoon even though the soil was damp. She might conclude that the plant needs more water. But wilting in the heat of the day can also be a way to reduce water loss, and the plant may recover by evening without any added water. Only after observing the plant over several days, and checking the soil at root depth rather than at the surface, can she tell which explanation fits.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It concludes that wilting always means the soil is dry."}, {"id": "B", "text": "It sets out an observation, offers a plausible explanation, then complicates it and proposes a way to test it."}, {"id": "C", "text": "It describes a controlled experiment that has already been completed."}, {"id": "D", "text": "It lists several unrelated reasons to grow tomatoes."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0054', 'B', ARRAY['B']::TEXT[], 'The movement is observation, quick explanation, alternative explanation, and a method for distinguishing them.', '{"D": "The passage is about one observation and its interpretation.", "A": "The text says wilting can also reduce water loss.", "C": "No experiment has been completed; the passage proposes observation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0055', 'HDSAT-RW-M10X-P0055', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'The oldest known shoes are sandals woven from sagebrush bark, found in a cave in Oregon and dated to roughly ten thousand years ago. The weave is not crude: the soles were made thicker than the straps, and the pattern varies by foot. Such details suggest that the makers were not merely protecting their feet from cold but designing for fit and wear. The sandals are older than agriculture in the region, a reminder that technological sophistication does not arrive in a fixed order.', 'Which choice best describes the function of the detail about the soles and straps?', '[{"id": "A", "text": "It explains why the sandals did not survive in other caves."}, {"id": "B", "text": "It proves that agriculture existed before the sandals."}, {"id": "C", "text": "It shows that the sandals were made for ceremonial use only."}, {"id": "D", "text": "It supports the claim that the sandals reflect deliberate design rather than mere protection."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0055', 'D', ARRAY['D']::TEXT[], 'The construction details are evidence for intention and fit, which is exactly the claim the next sentence states.', '{"C": "Ceremony is not mentioned.", "A": "Preservation conditions in other caves are not discussed.", "B": "The text says the sandals are older than agriculture in the region."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0056', 'HDSAT-RW-M10X-P0056', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Several deep-sea animals produce light, and the functions vary. Some flashes startle predators; others lure prey close. Still others appear to help members of the same species find one another in darkness. A single species may use light in more than one way, depending on the situation. General statements about why animals glow therefore tend to be true only in particular contexts.', 'Which choice best describes the function of the list of functions in the second and third sentences?', '[{"id": "A", "text": "It provides examples that support the passage''s caution about general explanations."}, {"id": "B", "text": "It introduces a single explanation that applies to every species."}, {"id": "C", "text": "It argues that deep-sea animals cannot see light."}, {"id": "D", "text": "It describes the anatomy of light-producing organs."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0056', 'A', ARRAY['A']::TEXT[], 'The catalog of uses leads directly to the conclusion that generalizations hold only in context.', '{"B": "The examples show different functions, not one universal explanation.", "D": "Anatomy is not described.", "C": "The passage implies the animals use light, which requires detection."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0057', 'HDSAT-RW-M10X-P0057', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Hard', 'multiple_choice', 'A proposal to reintroduce wolves to a national park met with objections from nearby ranchers, who feared losses of livestock. Supporters pointed to studies showing that wolves rarely attack cattle and that compensation programs can cover losses. The debate did not end there: even a small number of attacks can be costly for an individual rancher, and compensation can be slow. The disagreement, in other words, was less about averages than about who bears the risk.', 'Which choice best describes the function of the final sentence?', '[{"id": "A", "text": "It introduces new evidence about wolf behavior."}, {"id": "B", "text": "It reframes the dispute by identifying what the two sides were really disagreeing about."}, {"id": "C", "text": "It summarizes the scientific studies cited earlier."}, {"id": "D", "text": "It proposes that the reintroduction should be abandoned."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0057', 'B', ARRAY['B']::TEXT[], 'The last sentence shifts from competing facts to the underlying distributive question, which is a reframing.', '{"C": "The final sentence offers an interpretation, not a study summary.", "D": "No recommendation to abandon the plan is made.", "A": "No new behavioral evidence appears there."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0058', 'HDSAT-RW-M10X-P0058', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Easy', 'multiple_choice', 'The night sky over the Atacama Desert is exceptionally clear, and several of the world''s largest telescopes are sited there. The dryness that makes the sky transparent also makes the ground harsh: little rain falls, and dust can carry far when wind picks up. Astronomers have learned to schedule observations around seasonal dust and to design instruments that tolerate the conditions. The desert''s clarity and its difficulty come from the same climate.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It describes the history of one telescope in chronological order."}, {"id": "B", "text": "It argues that the Atacama is a poor location for telescopes."}, {"id": "C", "text": "It explains an advantage, then shows that the same conditions create a disadvantage and a need for adaptation."}, {"id": "D", "text": "It compares the Atacama with a desert that receives more rain."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0058', 'C', ARRAY['C']::TEXT[], 'The passage links the benefit and the cost to one cause, the dry climate, and notes how astronomers adapt.', '{"B": "The passage says several of the largest telescopes are sited there.", "D": "No other desert is introduced.", "A": "No single telescope''s history is narrated."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-P0059', 'HDSAT-RW-M10X-P0059', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'A map of a city''s trees can be read as a map of its history. Streets planted in the nineteenth century often carry a single species, chosen for uniformity and fast growth. Neighborhoods developed after the automobile tend to have younger, more varied plantings, because individual homeowners made the choices. Where a disease has swept through an older population, the pattern of empty pits still traces the original rows. The canopy records decisions that no one thought to write down.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It gives instructions for planting a city''s street trees."}, {"id": "B", "text": "It argues that all neighborhoods have identical tree cover."}, {"id": "C", "text": "It uses examples of planting patterns to support a claim about what the canopy records."}, {"id": "D", "text": "It explains how tree diseases spread between species."}]'::jsonb, NULL, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-P0059', 'C', ARRAY['C']::TEXT[], 'Each example shows a planting decision preserved in the canopy, which supports the closing claim about unwritten history.', '{"A": "The passage is descriptive, not a how-to.", "B": "It contrasts older and newer neighborhoods.", "D": "Disease is one example; the mechanism of spread is not explained."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-S0000', 'HDSAT-RW-M10X-S0000', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Hard', 'multiple_choice', 'While researching a topic, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0000', 'D', ARRAY['D']::TEXT[], 'The goal asks for both sides of one decision. The key pairs the conductivity figures from the second note with the degradation result from the third note, showing weaker insulation alongside easier disposal.', '{"A": "This choice gives only the insulation figures and says nothing about disposal, so it does not present a tradeoff.", "B": "This choice gives only the disposal result and omits the weaker insulation, so it presents no tradeoff either.", "C": "Cost is not part of the insulation-versus-disposal tradeoff the goal names."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-S0001', 'HDSAT-RW-M10X-S0001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Hard', 'multiple_choice', 'While researching a topic, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0001', 'C', ARRAY['C']::TEXT[], 'The key turns the two after-values into change scores (18 points versus 3 points) and keeps the starting values, which is exactly the comparison that shows the size of the sensor effect.', '{"D": "This choice notes the similar starting points but never reports how much each group improved.", "A": "This choice compares cost, not the change in compliance that the goal asks to emphasize.", "B": "This choice describes the reminder but gives no before-and-after figures."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-S0002', 'HDSAT-RW-M10X-S0002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Easy', 'multiple_choice', 'While researching a topic, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0002', 'D', ARRAY['D']::TEXT[], 'The key links the practice described in the first note (sorting during transit) to the outcome in the second note (transit time halved), which is the causal explanation the goal requests.', '{"A": "This choice describes the clerks'' working position but never connects it to faster delivery.", "B": "This choice gives the service''s end date, which does not explain the earlier speedup.", "C": "This choice reverses the notes, which say sorting happened aboard the moving cars."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-S0003', 'HDSAT-RW-M10X-S0003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Easy', 'multiple_choice', 'While researching a topic, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0003', 'D', ARRAY['D']::TEXT[], 'Only the key uses the comprehension result, the one note that measures how little untrained listeners understood.', '{"B": "This choice describes the language''s range, not how difficult it is for outsiders.", "A": "This choice gives recognition dates, which say nothing about comprehension by non-users.", "C": "This choice explains how the language works, not how poorly outsiders understand it."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-S0004', 'HDSAT-RW-M10X-S0004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Medium', 'multiple_choice', 'While researching a topic, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0004', 'B', ARRAY['B']::TEXT[], 'The key joins the comparison from the second note (8 times as many hedgehogs) to the price in the fourth note, which is what turns the finding into an affordable recommendation.', '{"C": "This choice states the decline but proposes nothing and uses none of the gap data.", "A": "This choice mentions the low cost but not the evidence that gaps help hedgehogs.", "D": "This choice reports sampling details without making a recommendation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-S0005', 'HDSAT-RW-M10X-S0005', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Medium', 'multiple_choice', 'While researching a topic, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0005', 'B', ARRAY['B']::TEXT[], 'The key uses the tension figure from the third note to explain the physical effect of the higher pitch named in the goal.', '{"C": "This choice gives the standardization date but no physical consequence of a higher pitch.", "D": "This choice states the historical range without explaining what a higher pitch does.", "A": "This choice reports a modern practice without any physical consequence."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-S0006', 'HDSAT-RW-M10X-S0006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Hard', 'multiple_choice', 'While researching a topic, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0006', 'B', ARRAY['B']::TEXT[], 'The key states the raw gain and converts it into a percentage, which shows the effect is real but modest, and it correctly notes that effort perception did not change.', '{"A": "This choice reports a side effect and says nothing about the size of the performance change.", "D": "This choice gives the sample size, not the effect.", "C": "This choice overstates the result and contradicts the notes, which found no change in perceived effort."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-S0007', 'HDSAT-RW-M10X-S0007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Medium', 'multiple_choice', 'While researching a topic, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0007', 'A', ARRAY['A']::TEXT[], 'The key uses the fourth note''s comparison directly: acidity followed lactic acid concentration, while yeast count did not.', '{"C": "This choice notes a shared feature, which cannot explain variation in acidity.", "D": "This choice describes a temperature effect on the yeast-bacteria ratio, not on acidity.", "B": "This choice describes the sampling design rather than the cause of acidity differences."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-S0008', 'HDSAT-RW-M10X-S0008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Medium', 'multiple_choice', 'While researching a topic, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0008', 'A', ARRAY['A']::TEXT[], 'The key states the method: the depth of the dip yields the ratio of planet radius to star radius, which the notes give as about 10 percent.', '{"B": "This choice gives the observing period and interval, not the size method.", "D": "This choice gives the star''s size, not how the planet''s size was found.", "C": "This choice contradicts the notes, which say the radius came from the dip depth, not an image."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-S0009', 'HDSAT-RW-M10X-S0009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Expression of Ideas', 'Rhetorical Synthesis', 'Medium', 'multiple_choice', 'While researching a topic, a student has taken the following notes:
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0009', 'B', ARRAY['B']::TEXT[], 'The key uses the fourth note, which explains that the porous clay absorbed the residues and held them until analysis.', '{"D": "This choice gives the detection count but not why the lipids persisted.", "A": "This choice reports what the residues were, not why they survived.", "C": "This choice gives the age and number of sites, which do not explain preservation."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
