INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0010', 'B', ARRAY['B']::TEXT[], 'The key states the before-and-after trip times, which is the direct measure of the saving the goal asks about.', '{"D": "This choice gives one cause of the saving but not the overall time saved.", "A": "This choice reports an effect on car traffic, not on bus trip time.", "C": "This choice describes the stations rather than the change in travel time."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
