INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0011', 'A', ARRAY['A']::TEXT[], 'The key pairs the recall figures from the second note with the self-rating from the fourth, which is the gap between what students believed and how they performed.', '{"B": "This choice establishes that study time was equal but does not mention the mismatch with self-ratings.", "C": "This choice gives the sample and task, not the mismatch.", "D": "This choice reports only the spaced group''s result and omits both the comparison and the ratings."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
