INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0012', 'C', ARRAY['C']::TEXT[], 'The key connects the overlap with traffic noise in the third note to the higher pitch observed in the second, giving a plausible acoustic explanation.', '{"D": "This choice gives the sample size and locations, not a cause.", "A": "This choice states the difference without offering any explanation for it.", "B": "This choice describes a preference that would work against, not explain, higher city pitch."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
