INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-S0013', 'A', ARRAY['A']::TEXT[], 'The key uses the fourth note''s assumption (vertical stakes) and states why violating it would bias the measurement, which is the limitation the goal asks for.', '{"B": "This choice reports the results, not a weakness in how they were obtained.", "C": "This choice gives the temperature trend, not a limitation of the method.", "D": "This choice describes the method without identifying its assumption."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
