INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0000', 'HDSAT-RW-M10X-Q0000', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A soil laboratory measured the percentage of organic matter in samples taken from four field plots. The results are shown in the table.', 'Which choice most effectively uses data from the table to complete the statement?', '[{"id": "A", "text": "Plots A and C recorded the same share of organic matter."}, {"id": "B", "text": "Plot A had the highest share of organic matter, at 2.4 percent."}, {"id": "C", "text": "Plot D had the highest share of organic matter, 3.9 percent, which was 0.8 percentage points above Plot B."}, {"id": "D", "text": "Plot B had the highest share of organic matter, at 3.1 percent."}]'::jsonb, '{"type": "table", "caption": "Organic matter in four field plots", "headers": ["Plot", "Organic matter (%)"], "rows": [["Plot A", "2.4"], ["Plot B", "3.1"], ["Plot C", "2.8"], ["Plot D", "3.9"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0000', 'C', ARRAY['C']::TEXT[], 'Plot D leads at 3.9 percent. Subtracting Plot B''s 3.1 percent gives a gap of 0.8 percentage points, which matches the correct statement.', '{"D": "Plot D''s 3.9 percent is higher than Plot B''s 3.1 percent, so B is not the highest.", "B": "Plot A''s 2.4 percent is the lowest value in the table, not the highest.", "A": "Plot A recorded 2.4 percent and Plot C recorded 2.8 percent, so the two differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0001', 'HDSAT-RW-M10X-Q0001', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A transport survey counted the average number of vehicle crossings per day on four city bridges. The counts are summarized in the table.', 'Which statement is best supported by the data in the table?', '[{"id": "A", "text": "Bridge 1 carried the fewest crossings, at 18,400 a day."}, {"id": "B", "text": "Every bridge carried more than 20,000 crossings a day."}, {"id": "C", "text": "Bridge 4 carried the most traffic, at 20,100 crossings a day."}, {"id": "D", "text": "Bridge 2 carried the most traffic, 22,750 crossings a day, or 2,650 more than Bridge 4."}]'::jsonb, '{"type": "table", "caption": "Average daily vehicle crossings", "headers": ["Bridge", "Crossings per day"], "rows": [["Bridge 1", "18,400"], ["Bridge 2", "22,750"], ["Bridge 3", "15,900"], ["Bridge 4", "20,100"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0001', 'D', ARRAY['D']::TEXT[], 'Bridge 2 is highest at 22,750 crossings a day. The difference from Bridge 4 is 22,750 minus 20,100, or 2,650 crossings.', '{"C": "Bridge 2''s 22,750 is higher than Bridge 4''s 20,100, so Bridge 4 is not the busiest.", "A": "Bridge 3 is lowest at 15,900, not Bridge 1 at 18,400.", "B": "Bridge 1 and Bridge 3 are both below 20,000 crossings a day."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0002', 'HDSAT-RW-M10X-Q0002', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'Four rain gauges in the same catchment recorded total annual rainfall. The totals appear in the table.', 'According to the table, which statement is true?', '[{"id": "A", "text": "All four gauges recorded more than 900 mm."}, {"id": "B", "text": "Gauge C recorded the most rainfall, 1,104 mm, or 292 mm more than Gauge A."}, {"id": "C", "text": "Gauge D recorded the least rainfall, at 878 mm."}, {"id": "D", "text": "Gauge B recorded the most rainfall, at 964 mm."}]'::jsonb, '{"type": "table", "caption": "Annual rainfall by gauge", "headers": ["Gauge", "Rainfall (mm)"], "rows": [["Gauge A", "812"], ["Gauge B", "964"], ["Gauge C", "1,104"], ["Gauge D", "878"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0002', 'B', ARRAY['B']::TEXT[], 'Gauge C is highest at 1,104 mm. Subtracting Gauge A''s 812 mm gives 292 mm, the difference named in the correct choice.', '{"D": "Gauge C''s 1,104 mm exceeds Gauge B''s 964 mm, so B is not the wettest.", "C": "Gauge A recorded 812 mm, which is lower than Gauge D''s 878 mm.", "A": "Gauge A and Gauge D both recorded less than 900 mm."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0003', 'HDSAT-RW-M10X-Q0003', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A materials laboratory tested four concrete mixes and recorded their compressive strength after 28 days. The results are shown in the table.', 'Which choice most effectively uses data from the table to complete the statement?', '[{"id": "A", "text": "Mix B was the strongest at 38.6 MPa, 1.2 MPa above Mix D."}, {"id": "B", "text": "Mix D was the strongest at 37.4 MPa."}, {"id": "C", "text": "Mixes A and D reached the same strength."}, {"id": "D", "text": "Mix C was the strongest at 31.9 MPa."}]'::jsonb, '{"type": "table", "caption": "Compressive strength of four mixes", "headers": ["Mix", "Strength (MPa)"], "rows": [["Mix A", "34.2"], ["Mix B", "38.6"], ["Mix C", "31.9"], ["Mix D", "37.4"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0003', 'A', ARRAY['A']::TEXT[], 'Mix B is highest at 38.6 MPa. The gap to Mix D is 38.6 minus 37.4, or 1.2 MPa.', '{"B": "Mix B''s 38.6 MPa is higher than Mix D''s 37.4 MPa, so Mix D is not the strongest.", "D": "Mix C''s 31.9 MPa is the lowest value in the table.", "C": "Mix A reached 34.2 MPa while Mix D reached 37.4 MPa, so they differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0004', 'HDSAT-RW-M10X-Q0004', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A health survey asked adults in four age groups how many hours they slept on an average night. The group averages are shown in the table.', 'Which statement is best supported by the data in the table?', '[{"id": "A", "text": "The 45-54 group slept the most, at 6.4 hours."}, {"id": "B", "text": "The 18-24 group slept the most, 8.9 hours, 1.8 hours more than the 35-44 group."}, {"id": "C", "text": "All four groups averaged more than 7.5 hours."}, {"id": "D", "text": "The 35-44 group slept the least, at 7.1 hours."}]'::jsonb, '{"type": "table", "caption": "Average nightly sleep by age group", "headers": ["Age group", "Sleep (hours)"], "rows": [["18-24", "8.9"], ["25-34", "7.7"], ["35-44", "7.1"], ["45-54", "6.4"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0004', 'B', ARRAY['B']::TEXT[], 'The youngest group is highest at 8.9 hours. Subtracting the 35-44 group''s 7.1 hours leaves 1.8 hours.', '{"A": "The 45-54 group has the lowest average in the table, not the highest.", "D": "The 45-54 group at 6.4 hours is lower than the 35-44 group at 7.1 hours.", "C": "The 35-44 and 45-54 groups both averaged below 7.5 hours."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
