INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0005', 'A', ARRAY['A']::TEXT[], 'Department B leads at 71 percent. The gap to Department D is 71 minus 59, or 12 percentage points.', '{"C": "Department B''s 71 percent is higher than Department C''s 68 percent.", "D": "Department D''s 59 percent is the lowest share in the table.", "B": "Departments A and D both fell below 65 percent."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0006', 'HDSAT-RW-M10X-Q0006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A city counted daily bicycle crossings on four bridges over the same week. The daily averages are shown in the table.', 'Which choice most effectively uses data from the table to complete the statement?', '[{"id": "A", "text": "Bridge C counted the most crossings, 4,110, which was 420 more than Bridge D."}, {"id": "B", "text": "Bridge B counted the most crossings, at 2,780."}, {"id": "C", "text": "Bridges A and C counted the same number of crossings."}, {"id": "D", "text": "Bridge D counted the most crossings, at 3,690."}]'::jsonb, '{"type": "table", "caption": "Daily bicycle crossings by bridge", "headers": ["Bridge", "Daily crossings"], "rows": [["Bridge A", "3,250"], ["Bridge B", "2,780"], ["Bridge C", "4,110"], ["Bridge D", "3,690"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0006', 'A', ARRAY['A']::TEXT[], 'Bridge C leads at 4,110 crossings. Subtracting Bridge D''s 3,690 gives 420, the gap stated in the correct choice.', '{"D": "Bridge C''s 4,110 is higher than Bridge D''s 3,690, so Bridge D is not highest.", "B": "Bridge B''s 2,780 is the lowest count in the table.", "C": "Bridge A counted 3,250 while Bridge C counted 4,110, so they differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0007', 'HDSAT-RW-M10X-Q0007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A beekeeping group measured the honey harvested from four apiaries during one season. The yields are listed in the table.', 'Which statement is best supported by the data in the table?', '[{"id": "A", "text": "Apiary D produced the most honey, at 29.4 kg."}, {"id": "B", "text": "Apiary B produced the most honey, 31.0 kg, 1.6 kg more than Apiary D."}, {"id": "C", "text": "Apiary A produced the most honey, at 24.5 kg."}, {"id": "D", "text": "Apiaries B and C produced the same amount."}]'::jsonb, '{"type": "table", "caption": "Honey harvested at four apiaries", "headers": ["Apiary", "Honey (kg)"], "rows": [["Apiary A", "24.5"], ["Apiary B", "31.0"], ["Apiary C", "27.8"], ["Apiary D", "29.4"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0007', 'B', ARRAY['B']::TEXT[], 'Apiary B is highest at 31.0 kg. The difference from Apiary D is 31.0 minus 29.4, or 1.6 kg.', '{"A": "Apiary B''s 31.0 kg is above Apiary D''s 29.4 kg, so Apiary D is not the top producer.", "C": "Apiary A''s 24.5 kg is the lowest yield in the table.", "D": "Apiary B produced 31.0 kg and Apiary C produced 27.8 kg, so the amounts differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0008', 'HDSAT-RW-M10X-Q0008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A university library counted the average number of loans per student in four faculties. The averages are shown in the table.', 'According to the table, which statement is true?', '[{"id": "A", "text": "Faculty C recorded the most loans per student, at 6.8."}, {"id": "B", "text": "Every faculty recorded more than 8 loans per student."}, {"id": "C", "text": "Faculty D recorded the most loans per student, at 8.1."}, {"id": "D", "text": "Faculty B recorded the most loans per student, 9.4, 1.3 more than Faculty D."}]'::jsonb, '{"type": "table", "caption": "Loans per student by faculty", "headers": ["Faculty", "Loans per student"], "rows": [["Faculty A", "7.2"], ["Faculty B", "9.4"], ["Faculty C", "6.8"], ["Faculty D", "8.1"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0008', 'D', ARRAY['D']::TEXT[], 'Faculty B leads at 9.4 loans per student. Subtracting Faculty D''s 8.1 gives 1.3.', '{"C": "Faculty B''s 9.4 is higher than Faculty D''s 8.1, so Faculty D is not highest.", "A": "Faculty C''s 6.8 is the lowest average in the table.", "B": "Faculties A and C both averaged below 8 loans per student."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0009', 'HDSAT-RW-M10X-Q0009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A recycling scheme measured the share of contaminated material in four collection rounds. The rates are shown in the table.', 'Which choice most effectively uses data from the table to complete the statement?', '[{"id": "A", "text": "Round C had the highest contamination rate, 14.1 percent, 4.3 percentage points above Round B."}, {"id": "B", "text": "Round B had the highest contamination rate, at 9.8 percent."}, {"id": "C", "text": "Round A had the highest contamination rate, at 12.4 percent."}, {"id": "D", "text": "Rounds B and D had the same contamination rate."}]'::jsonb, '{"type": "table", "caption": "Contamination rate by collection round", "headers": ["Round", "Contamination (%)"], "rows": [["Round A", "12.4"], ["Round B", "9.8"], ["Round C", "14.1"], ["Round D", "11.2"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0009', 'A', ARRAY['A']::TEXT[], 'Round C is highest at 14.1 percent. The gap to Round B is 14.1 minus 9.8, or 4.3 percentage points.', '{"C": "Round C''s 14.1 percent is higher than Round A''s 12.4 percent.", "B": "Round B''s 9.8 percent is the lowest rate in the table.", "D": "Round B recorded 9.8 percent while Round D recorded 11.2 percent, so they differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
