INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0010', 'B', ARRAY['B']::TEXT[], 'Site C leads at 505 shoots per square meter. The difference from Site D is 505 minus 476, or 29.', '{"C": "Site C''s 505 is higher than Site D''s 476, so Site D is not the densest.", "D": "Site B''s 358 is the lowest density in the table.", "A": "Site A recorded 412 shoots per square meter while Site D recorded 476, so they differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
