INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0016', 'C', ARRAY['C']::TEXT[], 'Ladder C leads at 249 fish. Subtracting Ladder A''s 214 gives 35.', '{"A": "Ladder C''s 249 is above Ladder A''s 214, so Ladder A is not highest.", "B": "Ladder B''s 168 is the lowest count in the table.", "D": "Ladder B counted 168 fish while Ladder D counted 196, so they differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0017', 'HDSAT-RW-M10X-Q0017', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'A rail operator measured the share of morning trains arriving on time at four stations. The shares are shown in the table.', 'According to the table, which statement is true?', '[{"id": "A", "text": "Station A had the best punctuality, at 91.2 percent."}, {"id": "B", "text": "Station B had the best punctuality, at 87.5 percent."}, {"id": "C", "text": "Station C had the best punctuality, 94.8 percent, 3.6 percentage points above Station A."}, {"id": "D", "text": "Every station reached at least 92 percent."}]'::jsonb, '{"type": "table", "caption": "On-time arrivals by station", "headers": ["Station", "On-time arrivals (%)"], "rows": [["Station A", "91.2"], ["Station B", "87.5"], ["Station C", "94.8"], ["Station D", "89.6"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0017', 'C', ARRAY['C']::TEXT[], 'Station C leads at 94.8 percent. The gap to Station A is 94.8 minus 91.2, or 3.6 percentage points.', '{"A": "Station C''s 94.8 percent is above Station A''s 91.2 percent.", "B": "Station B''s 87.5 percent is the lowest share in the table.", "D": "Stations A, B and D all fell below 92 percent."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0018', 'HDSAT-RW-M10X-Q0018', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'A greenhouse trial measured leaf area on plants grown under four fertiliser treatments. The averages are shown in the table.', 'Which choice most effectively uses data from the table to complete the statement?', '[{"id": "A", "text": "Treatments A and C produced equal leaf areas."}, {"id": "B", "text": "Treatment C produced the largest leaf area, at 49.1 cm2."}, {"id": "C", "text": "Treatment B produced the largest leaf area, at 52.4 cm2."}, {"id": "D", "text": "Treatment D produced the largest leaf area, 55.7 cm2, 3.3 cm2 more than Treatment B."}]'::jsonb, '{"type": "table", "caption": "Leaf area by fertiliser treatment", "headers": ["Treatment", "Leaf area (cm2)"], "rows": [["Treatment A", "46.8"], ["Treatment B", "52.4"], ["Treatment C", "49.1"], ["Treatment D", "55.7"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0018', 'D', ARRAY['D']::TEXT[], 'Treatment D leads at 55.7 cm2. Subtracting Treatment B''s 52.4 gives 3.3 cm2.', '{"C": "Treatment D''s 55.7 cm2 is above Treatment B''s 52.4 cm2.", "B": "Treatment C''s 49.1 cm2 is below both Treatment B and Treatment D.", "A": "Treatment A measured 46.8 cm2 while Treatment C measured 49.1 cm2, so they differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0019', 'HDSAT-RW-M10X-Q0019', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A health team recorded the share of households with safe drinking water in four districts. The shares are shown in the table.', 'Which statement is best supported by the data in the table?', '[{"id": "A", "text": "District C had the highest share with safe water, 81 percent, 13 percentage points above District A."}, {"id": "B", "text": "District D had the highest share, at 77 percent."}, {"id": "C", "text": "District A had the highest share, at 68 percent."}, {"id": "D", "text": "Districts B and D had equal shares."}]'::jsonb, '{"type": "table", "caption": "Households with safe drinking water", "headers": ["District", "Households with safe water (%)"], "rows": [["District A", "68"], ["District B", "74"], ["District C", "81"], ["District D", "77"]]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0019', 'A', ARRAY['A']::TEXT[], 'District C leads at 81 percent. The gap to District A is 81 minus 68, or 13 percentage points.', '{"B": "District C''s 81 percent is above District D''s 77 percent.", "C": "District A''s 68 percent is the lowest share in the table.", "D": "District B recorded 74 percent while District D recorded 77 percent, so they differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0020', 'HDSAT-RW-M10X-Q0020', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A city parks department counted the trees planted by four schools during a spring programme. The counts are shown in the graph.', 'Which choice best describes the data in the graph?', '[{"id": "A", "text": "School B planted the most trees, 410, which was 135 more than School C."}, {"id": "B", "text": "School D planted the most trees, at 360."}, {"id": "C", "text": "School A planted the fewest trees, at 320."}, {"id": "D", "text": "Schools B and D planted the same number of trees."}]'::jsonb, '{"type": "bar_chart", "caption": "Trees planted by school", "x_label": "School", "y_label": "Trees planted", "series": [{"label": "School A", "value": 320}, {"label": "School B", "value": 410}, {"label": "School C", "value": 275}, {"label": "School D", "value": 360}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0020', 'A', ARRAY['A']::TEXT[], 'School B leads at 410 trees. The difference from School C is 410 minus 275, or 135.', '{"B": "School B''s 410 is higher than School D''s 360, so School D did not plant the most.", "C": "School C planted 275 trees, which is fewer than School A''s 320.", "D": "School B planted 410 trees while School D planted 360, so the totals differ."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0021', 'HDSAT-RW-M10X-Q0021', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A water utility recorded average daily household consumption in four neighbourhoods. The averages are shown in the graph.', 'Which statement about the data in the graph is true?', '[{"id": "A", "text": "Neighbourhood B used the most water, at 132 liters per household a day."}, {"id": "B", "text": "Neighbourhood A used the most water, at 148 liters per household a day."}, {"id": "C", "text": "Neighbourhood C used the most water, 165 liters per household a day, 44 more than Neighbourhood D."}, {"id": "D", "text": "Every neighbourhood used more than 140 liters per household a day."}]'::jsonb, '{"type": "bar_chart", "caption": "Daily household water use", "x_label": "Neighbourhood", "y_label": "Liters per household", "series": [{"label": "Neighbourhood A", "value": 148}, {"label": "Neighbourhood B", "value": 132}, {"label": "Neighbourhood C", "value": 165}, {"label": "Neighbourhood D", "value": 121}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
