INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0022', 'HDSAT-RW-M10X-Q0022', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'A sports laboratory measured twenty-metre sprint times for four training groups. Lower times are faster. The results are shown in the graph.', 'Which choice best describes the data in the graph?', '[{"id": "A", "text": "Group B was the fastest, finishing in 3.28 seconds, 0.14 second faster than Group A."}, {"id": "B", "text": "Group D was the fastest, finishing in 3.36 seconds."}, {"id": "C", "text": "Every group finished in under 3.30 seconds."}, {"id": "D", "text": "Group C was the fastest, finishing in 3.51 seconds."}]'::jsonb, '{"type": "bar_chart", "caption": "Twenty-metre sprint time by group", "x_label": "Group", "y_label": "Time (seconds)", "series": [{"label": "Group A", "value": 3.42}, {"label": "Group B", "value": 3.28}, {"label": "Group C", "value": 3.51}, {"label": "Group D", "value": 3.36}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
