INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0042', 'HDSAT-RW-M10X-Q0042', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A soil monitoring station measured moisture in the topsoil each week for five weeks. The readings are shown in the graph.', 'Which choice best describes the trend shown in the graph?', '[{"id": "A", "text": "Moisture rose from week 1 to week 5."}, {"id": "B", "text": "Moisture declined each week, dropping 15 percentage points from week 1 to week 5."}, {"id": "C", "text": "Moisture was lowest in week 1 at 34 percent."}, {"id": "D", "text": "Moisture stayed above 25 percent in every week."}]'::jsonb, '{"type": "line_chart", "caption": "Topsoil moisture over five weeks", "x_label": "Week", "y_label": "Moisture (%)", "series": [{"label": "Week 1", "value": 34}, {"label": "Week 2", "value": 31}, {"label": "Week 3", "value": 27}, {"label": "Week 4", "value": 22}, {"label": "Week 5", "value": 19}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0042', 'B', ARRAY['B']::TEXT[], 'Each week is lower than the last, from 34 percent to 19 percent, a total decline of 15 percentage points.', '{"A": "Every reading is lower than the one before it, so moisture fell rather than rose.", "C": "Week 1 has the highest reading in the graph, not the lowest.", "D": "Weeks 4 and 5 both fell below 25 percent."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0043', 'HDSAT-RW-M10X-Q0043', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A solar array''s monthly output was recorded from January to June. The output is shown in the graph.', 'Which statement about the data in the graph is true?', '[{"id": "A", "text": "Output rose every month from January to June."}, {"id": "B", "text": "Output was highest in June at 29 MW."}, {"id": "C", "text": "Output rose from January to April, then declined through June."}, {"id": "D", "text": "Output in January was higher than in April."}]'::jsonb, '{"type": "line_chart", "caption": "Monthly solar output", "x_label": "Month", "y_label": "Output (MW)", "series": [{"label": "January", "value": 18}, {"label": "February", "value": 24}, {"label": "March", "value": 31}, {"label": "April", "value": 38}, {"label": "May", "value": 35}, {"label": "June", "value": 29}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0043', 'C', ARRAY['C']::TEXT[], 'The graph rises from 18 MW in January to 38 MW in April, then falls to 35 MW and 29 MW.', '{"A": "Output fell from April to June, so it did not rise every month.", "B": "June''s 29 MW is below the April peak of 38 MW.", "D": "January''s 18 MW is below April''s 38 MW."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0044', 'HDSAT-RW-M10X-Q0044', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A hospital recorded admissions in each quarter of one year. The totals are shown in the graph.', 'Which choice best describes the data in the graph?', '[{"id": "A", "text": "Admissions peaked in the third quarter at 510, 90 more than in the first quarter."}, {"id": "B", "text": "Admissions rose in every quarter."}, {"id": "C", "text": "Admissions were lowest in the third quarter at 510."}, {"id": "D", "text": "Admissions in the fourth quarter exceeded those in the third."}]'::jsonb, '{"type": "line_chart", "caption": "Hospital admissions by quarter", "x_label": "Quarter", "y_label": "Admissions", "series": [{"label": "Q1", "value": 420}, {"label": "Q2", "value": 465}, {"label": "Q3", "value": 510}, {"label": "Q4", "value": 480}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0044', 'A', ARRAY['A']::TEXT[], 'The peak is Q3 at 510. Subtracting Q1''s 420 gives 90 admissions.', '{"B": "Admissions fell from the third quarter to the fourth, so they did not rise every quarter.", "C": "510 is the highest reading in the graph, not the lowest.", "D": "The fourth quarter recorded 480, which is below the third quarter''s 510."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0045', 'HDSAT-RW-M10X-Q0045', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A weather station recorded the average monthly temperature from March to July. The averages are shown in the graph.', 'Which statement about the data in the graph is true?', '[{"id": "A", "text": "The average temperature changed by less than 10 C across the period."}, {"id": "B", "text": "The average temperature rose each month, from 4.2 C in March to 20.4 C in July."}, {"id": "C", "text": "The average temperature fell from March to July."}, {"id": "D", "text": "The average temperature was highest in March at 4.2 C."}]'::jsonb, '{"type": "line_chart", "caption": "Average monthly temperature, March to July", "x_label": "Month", "y_label": "Temperature (C)", "series": [{"label": "March", "value": 4.2}, {"label": "April", "value": 6.8}, {"label": "May", "value": 11.5}, {"label": "June", "value": 16.1}, {"label": "July", "value": 20.4}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0045', 'B', ARRAY['B']::TEXT[], 'Every point is above the one before it, ending at 20.4 C, which is 16.2 C above the March value.', '{"C": "Each reading is higher than the previous one, so the temperature rose.", "D": "March has the lowest reading, not the highest.", "A": "The change is 20.4 minus 4.2, or 16.2 C, which is more than 10 C."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0046', 'HDSAT-RW-M10X-Q0046', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A library recorded visits in thousands for each month from January to June. The totals are shown in the graph.', 'Which choice best describes the data in the graph?', '[{"id": "A", "text": "Visits were highest in May at 27 thousand, 9 thousand more than in January."}, {"id": "B", "text": "Visits rose every month from January to June."}, {"id": "C", "text": "Visits were highest in January at 18 thousand."}, {"id": "D", "text": "Visits in June exceeded visits in May."}]'::jsonb, '{"type": "line_chart", "caption": "Library visits by month", "x_label": "Month", "y_label": "Visits (thousands)", "series": [{"label": "January", "value": 18}, {"label": "February", "value": 21}, {"label": "March", "value": 19}, {"label": "April", "value": 24}, {"label": "May", "value": 27}, {"label": "June", "value": 23}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0046', 'A', ARRAY['A']::TEXT[], 'The highest point is May at 27 thousand. Subtracting January''s 18 thousand gives 9 thousand.', '{"B": "Visits fell from February to March and from May to June, so they did not rise every month.", "C": "January''s 18 thousand is the lowest total in the graph.", "D": "June''s 23 thousand is below May''s 27 thousand."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0047', 'HDSAT-RW-M10X-Q0047', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A transport agency estimated the share of new vehicles that were electric in each year from 2019 to 2024. The shares are shown in the graph.', 'Which statement about the data in the graph is true?', '[{"id": "A", "text": "The share rose every year, from 2.1 percent in 2019 to 13.9 percent in 2024."}, {"id": "B", "text": "The share fell after 2022."}, {"id": "C", "text": "The share reached 20 percent by 2024."}, {"id": "D", "text": "The share was unchanged between 2020 and 2021."}]'::jsonb, '{"type": "line_chart", "caption": "Electric share of new vehicles", "x_label": "Year", "y_label": "Share (%)", "series": [{"label": "2019", "value": 2.1}, {"label": "2020", "value": 3.4}, {"label": "2021", "value": 5.2}, {"label": "2022", "value": 7.8}, {"label": "2023", "value": 10.6}, {"label": "2024", "value": 13.9}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0047', 'A', ARRAY['A']::TEXT[], 'Each year is above the previous one, ending at 13.9 percent, more than six times the 2019 value.', '{"B": "The readings from 2022 onward are higher than the one before them, so the share did not fall.", "D": "The share moved from 3.4 percent in 2020 to 5.2 percent in 2021.", "C": "The 2024 value is 13.9 percent, not 20 percent."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0048', 'HDSAT-RW-M10X-Q0048', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'A clinic measured the average wait before triage over five weeks. The averages are shown in the graph.', 'Which choice best describes the trend shown in the graph?', '[{"id": "A", "text": "The wait was shortest in week 1 at 14 minutes."}, {"id": "B", "text": "The wait was shortest in week 5 at 9 minutes, 7 minutes less than in week 3."}, {"id": "C", "text": "The wait rose every week from week 1 to week 5."}, {"id": "D", "text": "The wait never fell below 12 minutes."}]'::jsonb, '{"type": "line_chart", "caption": "Average wait before triage", "x_label": "Week", "y_label": "Wait (minutes)", "series": [{"label": "Week 1", "value": 14}, {"label": "Week 2", "value": 12}, {"label": "Week 3", "value": 16}, {"label": "Week 4", "value": 11}, {"label": "Week 5", "value": 9}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0048', 'B', ARRAY['B']::TEXT[], 'The lowest point is week 5 at 9 minutes. Subtracting it from week 3''s 16 minutes gives 7.', '{"C": "The wait fell from week 1 to week 2 and from week 3 to week 4, so it did not rise every week.", "A": "Week 1''s 14 minutes is higher than the final three readings.", "D": "Weeks 4 and 5 recorded 11 and 9 minutes, both below 12."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
