INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M10X-Q0049', 'C', ARRAY['C']::TEXT[], 'The highest point is season 5 at 7.2. Subtracting season 3''s 5.9 gives 1.3 tonnes per hectare.', '{"B": "Season 3''s 5.9 tonnes per hectare is the lowest value in the graph.", "A": "Yield rose in seasons 2, 4 and 5, so it did not fall every season.", "D": "Season 5''s 7.2 tonnes per hectare is above season 1''s 6.1."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0050', 'HDSAT-RW-M10X-Q0050', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Medium', 'multiple_choice', 'A weather station recorded monthly rainfall from January to June. The totals are shown in the graph.', 'Which choice best describes the data in the graph?', '[{"id": "A", "text": "Rainfall in April exceeded rainfall in March."}, {"id": "B", "text": "Rainfall rose every month from January to June."}, {"id": "C", "text": "Rainfall was lowest in April at 39 mm, 52 mm less than in June."}, {"id": "D", "text": "Rainfall was lowest in June at 91 mm."}]'::jsonb, '{"type": "line_chart", "caption": "Monthly rainfall, January to June", "x_label": "Month", "y_label": "Rainfall (mm)", "series": [{"label": "January", "value": 82}, {"label": "February", "value": 64}, {"label": "March", "value": 47}, {"label": "April", "value": 39}, {"label": "May", "value": 58}, {"label": "June", "value": 91}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
