INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0052', 'HDSAT-RW-M10X-Q0052', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Hard', 'multiple_choice', 'A transit agency recorded bus ridership in thousands over five years. The totals are shown in the graph.', 'Which choice best describes the trend shown in the graph?', '[{"id": "A", "text": "Ridership was lowest in the final year."}, {"id": "B", "text": "Ridership rose in every year."}, {"id": "C", "text": "Ridership ended below its starting level."}, {"id": "D", "text": "Ridership fell for three years before rising, and ended 3 thousand above its starting level."}]'::jsonb, '{"type": "line_chart", "caption": "Bus ridership over five years", "x_label": "Year", "y_label": "Ridership (thousands)", "series": [{"label": "2019", "value": 52}, {"label": "2020", "value": 48}, {"label": "2021", "value": 44}, {"label": "2022", "value": 47}, {"label": "2023", "value": 55}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
