INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M10X-Q0053', 'HDSAT-RW-M10X-Q0053', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Quantitative)', 'Easy', 'multiple_choice', 'A school recorded the average test score in each of five terms. The averages are shown in the graph.', 'Which statement about the data in the graph is true?', '[{"id": "A", "text": "The average changed by fewer than 5 points overall."}, {"id": "B", "text": "The average fell overall."}, {"id": "C", "text": "The average rose by 11 points overall, from 61 in the first term to 72 in the fifth."}, {"id": "D", "text": "The average was highest in the first term at 61."}]'::jsonb, '{"type": "line_chart", "caption": "Average test score by term", "x_label": "Term", "y_label": "Average score", "series": [{"label": "Term 1", "value": 61}, {"label": "Term 2", "value": 64}, {"label": "Term 3", "value": 63}, {"label": "Term 4", "value": 68}, {"label": "Term 5", "value": 72}]}'::jsonb, 'hdsat-open-core-2026', 'HDSAT Open Core Curated Bank', 'CC-BY-4.0', 'HDSAT Open Core Curated Bank (CC-BY-4.0)', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
